window.TEXTBOOK_TEXTS = Object.assign(window.TEXTBOOK_TEXTS || {}, {"hsk1-1":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"AI小语，你好！","pinyin":"AI Xiǎoyǔ, nǐ hǎo!","speaker":"王一飞","vi":"Chào AI Tiểu Ngữ!"},{"hanzi":"王老师，你好！","pinyin":"Wáng lǎoshī, nǐ hǎo!","speaker":"小语","vi":"Chào cô Vương!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong phần bối cảnh có câu \"开学第一天，在办公室里，王一飞和AI助教小语打招呼。\" (Ngày đầu tiên khai giảng, trong văn phòng, Vương Nhất Phi và trợ giảng AI Tiểu Ngữ chào hỏi nhau), nên đáp án đúng là 在办公室里.","options":["在教室里","在办公室里","在校园里","在家里"],"q":"王一飞和小语在哪里打招呼？"},{"answerIdx":0,"explanation":"Trong bài có câu 小语 nói \"王老师，你好！\" (Thầy/Cô Vương, chào thầy/cô!), nên đáp án đúng là 王老师，你好！.","options":["王老师，你好！","同学们，再见！","老师，您好！","王老师，谢谢！"],"q":"小语怎么跟王一飞打招呼？"}],"scene":"开学第一天，在办公室里，王一飞和AI助教小语打招呼。","sceneVi":"Ngày đầu tiên khai giảng, trong văn phòng, Vương Nhất Phi chào hỏi trợ giảng AI Tiểu Ngữ."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"大家好！","pinyin":"Dàjiā hǎo!","speaker":"王一飞","vi":"Chào mọi người!"},{"hanzi":"老师，您好！","pinyin":"Lǎoshī, nín hǎo!","speaker":"学生们","vi":"Chúng em chào cô ạ!"},{"hanzi":"你们好！","pinyin":"Nǐmen hǎo!","speaker":"小语","vi":"Chào các bạn!"},{"hanzi":"你好，小语！","pinyin":"Nǐ hǎo, Xiǎoyǔ!","speaker":"学生们","vi":"Chào Tiểu Ngữ!"}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu 学生们 nói \"老师，您好！\" (Em chào thầy/cô ạ!), dùng từ kính trọng 您 để chào giáo viên, nên đáp án đúng là 老师，您好！.","options":["大家好！","你们好！","老师，您好！","你好，小语！"],"q":"学生们怎么向王老师打招呼？"},{"answerIdx":1,"explanation":"Trong bài có câu thoại của 小语 là \"你们好！\" (Chào các bạn!), nên người nói câu này là 小语.","options":["王一飞","小语","学生们","白家月"],"q":"“你们好！”是谁说的话？"}],"scene":"开学第一天，课堂上，学生们学习打招呼用语。","sceneVi":"Ngày đầu tiên khai giảng, trên lớp học, các học sinh học các câu chào hỏi."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"谢谢！","pinyin":"Xièxie!","speaker":"学生们","vi":"Cảm ơn!"},{"hanzi":"不客气！","pinyin":"Bú kèqi!","speaker":"小语","vi":"Không có gì!"},{"hanzi":"同学们，再见！","pinyin":"Tóngxuémen, zàijiàn!","speaker":"王一飞","vi":"Tạm biệt các em!"},{"hanzi":"老师，再见！","pinyin":"Lǎoshī, zàijiàn!","speaker":"学生们","vi":"Tạm biệt cô ạ!"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có đoạn đối thoại 学生们 nói \"谢谢！\" (Cảm ơn!) và 小语 đáp lại \"不客气！\" (Không có gì!), nên đáp án đúng là 不客气！.","options":["不客气！","没关系！","同学们，再见！","你们好！"],"q":"学生们说“谢谢！”以后，小语怎么回答？"},{"answerIdx":3,"explanation":"Trong bài có câu 王一飞 nói \"同学们，再见！\" (Tạm biệt các em!), nên đáp án đúng là 同学们，再见！.","options":["老师，再见！","谢谢！","大家好！","同学们，再见！"],"q":"王一飞下课时对学生们说什么？"}],"scene":"开学第一天，课堂上，学生们学习致谢语、告别语。","sceneVi":"Ngày đầu tiên khai giảng, trên lớp học, các học sinh học câu cảm ơn và câu tạm biệt."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (绕口令)","lines":[{"hanzi":"妈种麻，我放马。","pinyin":"Mā zhòng má, wǒ fàng mǎ.","speaker":"绕口令","vi":"Mẹ trồng gai, tôi chăn ngựa."},{"hanzi":"马吃麻，妈骂马。","pinyin":"Mǎ chī má, mā mà mǎ.","speaker":"绕口令","vi":"Ngựa ăn gai, mẹ mắng ngựa."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài đọc líu lưỡi có câu \"妈种麻，我放马。\" (Mẹ trồng cây gai, tôi chăn ngựa), nên việc người mẹ làm là 种麻.","options":["放马","吃麻","种麻","打招呼"],"q":"绕口令里，妈妈在做什么？"},{"answerIdx":0,"explanation":"Trong bài có câu \"马吃麻，妈骂马。\" (Ngựa ăn cây gai, mẹ mắng ngựa), cho thấy mẹ mắng ngựa vì ngựa đã ăn cây gai mẹ trồng, nên đáp án đúng là 因为马吃了妈妈种的麻.","options":["因为马吃了妈妈种的麻","因为马没有吃麻","因为我不放马","因为妈妈不喜欢马"],"q":"为什么妈妈骂马？"}],"scene":"跟读绕口令","sceneVi":"Đọc theo câu nói líu lưỡi."}],"hsk1-2":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"请问，你叫什么名字？","pinyin":"Qǐngwèn, nǐ jiào shénme míngzi?","speaker":"王一飞","vi":"Xin hỏi, em tên là gì?"},{"hanzi":"我叫陈天中。","pinyin":"Wǒ jiào Chén Tiānzhōng.","speaker":"陈天中","vi":"Em tên là Trần Thiên Trung."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong phần bối cảnh có câu \"在教室里，王一飞在认识学生。\" (Trong lớp học, Vương Nhất Phi đang làm quen với học sinh), nên cô hỏi tên nhằm mục đích làm quen với học sinh (她想认识学生).","options":["她想认识学生","她想跟学生说再见","她认错了人","她想感谢学生"],"q":"王一飞为什么问“请问，你叫什么名字？”？"},{"answerIdx":1,"explanation":"Trong bài có câu học sinh trả lời \"我叫陈天中。\" (Em tên là Trần Thiên Trung), nên đáp án đúng là 陈天中.","options":["李文","陈天中","白家月","杨同乐"],"q":"回答王一飞的学生叫什么名字？"}],"scene":"在教室里，王一飞在认识学生。","sceneVi":"Trong phòng học, Vương Nhất Phi đang làm quen với học sinh."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你好，安妮！","pinyin":"Nǐ hǎo, Ānnī!","speaker":"陈天中","vi":"Chào cậu, Annie!"},{"hanzi":"你好，陈天中！我不是安妮，我是白家月。","pinyin":"Nǐ hǎo, Chén Tiānzhōng! Wǒ bú shì Ānnī, wǒ shì Bái Jiāyuè.","speaker":"白家月","vi":"Chào Trần Thiên Trung! Mình không phải là Annie, mình là Bạch Gia Nguyệt."},{"hanzi":"对不起！","pinyin":"Duìbuqǐ!","speaker":"陈天中","vi":"Xin lỗi nhé!"},{"hanzi":"没关系！","pinyin":"Méi guānxi!","speaker":"白家月","vi":"Không sao đâu!"}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu 陈天中 gọi \"你好，安妮！\" và 白家月 đính chính \"我不是安妮，我是白家月。\" (Mình không phải An Ni, mình là Bạch Gia Nguyệt), nên Trần Thiên Trung xin lỗi vì đã nhận nhầm Bạch Gia Nguyệt thành An Ni.","options":["因为他迟到了","因为他不知道白家月的名字","因为他把白家月认成安妮了","因为他忘了打招呼"],"q":"陈天中为什么说“对不起！”？"},{"answerIdx":1,"explanation":"Trong bài có câu 白家月 đáp lại lời xin lỗi bằng câu \"没关系！\" (Không sao đâu!), nên đáp án đúng là 没关系！.","options":["不客气！","没关系！","谢谢！","再见！"],"q":"听到“对不起！”以后，白家月怎么回答？"}],"scene":"在校园里，陈天中和白家月打招呼时认错了人。","sceneVi":"Trong khuôn viên trường, khi chào hỏi Bạch Gia Nguyệt, Trần Thiên Trung đã nhận nhầm người."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"你好！我叫李文。","pinyin":"Nǐ hǎo! Wǒ jiào Lǐ Wén.","speaker":"李文","vi":"Chào bạn! Mình tên là Lý Văn."},{"hanzi":"你好！我叫白家月。","pinyin":"Nǐ hǎo! Wǒ jiào Bái Jiāyuè.","speaker":"白家月","vi":"Chào bạn! Mình tên là Bạch Gia Nguyệt."},{"hanzi":"很高兴认识你。","pinyin":"Hěn gāoxìng rènshi nǐ.","speaker":"李文","vi":"Rất vui được làm quen với bạn."},{"hanzi":"认识你我也很高兴。","pinyin":"Rènshi nǐ wǒ yě hěn gāoxìng.","speaker":"白家月","vi":"Làm quen với bạn mình cũng rất vui."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong phần bối cảnh có câu \"在校园里，李文和白家月第一次相遇。\" (Trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt lần đầu gặp nhau), kết hợp với phần tự giới thiệu tên và câu \"很高兴认识你。\" (Rất vui được làm quen với bạn), nên đáp án đúng là 他们刚认识，第一次见面.","options":["他们是老朋友","他们是老师和学生","他们刚认识，第一次见面","他们是哥哥和妹妹"],"q":"李文和白家月是什么关系？"},{"answerIdx":2,"explanation":"Trong bài có hai câu \"很高兴认识你。\" (Rất vui được làm quen với bạn) và \"认识你我也很高兴。\" (Quen biết bạn mình cũng rất vui), cho thấy cả Lý Văn và Bạch Gia Nguyệt đều rất vui khi quen nhau.","options":["只有李文很高兴","白家月认识李文不太高兴","李文和白家月都很高兴认识对方","李文不知道白家月叫什么名字"],"q":"关于这段对话，下面哪句话是对的？"}],"scene":"在校园里，李文和白家月第一次相遇。","sceneVi":"Trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt lần đầu tiên gặp nhau."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (绕口令)","lines":[{"hanzi":"七加一，再减一，加完减完等于几？","pinyin":"Qī jiā yī, zài jiǎn yī, jiāwán jiǎnwán děngyú jǐ?","speaker":"绕口令","vi":"Bảy cộng một, lại trừ một, cộng xong trừ xong bằng mấy?"},{"hanzi":"加完减完还是七。","pinyin":"Jiāwán jiǎnwán hái shì qī.","speaker":"绕口令","vi":"Cộng xong trừ xong vẫn là bảy."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"七加一，再减一，加完减完等于几？\" (Bảy cộng một, rồi trừ một, cộng xong trừ xong bằng mấy?), nên thứ tự phép tính là 先加一，再减一.","options":["先加一，再减一","先减一，再加一","先加七，再减七","先加一，再加一"],"q":"绕口令里说七先做什么，再做什么？"},{"answerIdx":1,"explanation":"Trong bài có câu trả lời \"加完减完还是七。\" (Cộng xong trừ xong vẫn là bảy), nên đáp án đúng là 等于七.","options":["等于六","等于七","等于八","等于一"],"q":"七加一再减一，最后等于几？"}],"scene":"跟读绕口令","sceneVi":"Đọc theo câu nói líu lưỡi."}],"hsk1-3":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"我是中国人。","pinyin":"Wǒ shì Zhōngguó rén.","speaker":"李文","vi":"Tôi là người Trung Quốc."},{"hanzi":"我是法国人。我的中文老师也是中国人。","pinyin":"Wǒ shì Fǎguó rén. Wǒ de Zhōngwén lǎoshī yě shì Zhōngguó rén.","speaker":"白家月","vi":"Tôi là người Pháp. Giáo viên tiếng Trung của tôi cũng là người Trung Quốc."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu 白家月 nói \"我是法国人。\" (Tôi là người Pháp), nên đáp án đúng là 法国人.","options":["中国人","泰国人","法国人","美国人"],"q":"白家月是哪国人？"},{"answerIdx":1,"explanation":"Trong bài có câu \"我的中文老师也是中国人。\" (Giáo viên tiếng Trung của tôi cũng là người Trung Quốc), nên đáp án đúng là 中国人.","options":["法国人","中国人","泰国人","李文"],"q":"白家月的中文老师是哪国人？"}],"scene":"在校园里，李文和白家月第一次相遇，两人继续聊天儿。","sceneVi":"Trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt lần đầu gặp nhau, hai người tiếp tục trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"这是谁？","pinyin":"Zhè shì shéi?","speaker":"安妮","vi":"Đây là ai?"},{"hanzi":"这是我女朋友。","pinyin":"Zhè shì wǒ nǚpéngyou.","speaker":"陈天中","vi":"Đây là bạn gái của tôi."},{"hanzi":"你女朋友是哪国人？","pinyin":"Nǐ nǚpéngyou shì nǎ guó rén?","speaker":"安妮","vi":"Bạn gái của bạn là người nước nào?"},{"hanzi":"她也是泰国人。","pinyin":"Tā yě shì Tàiguó rén.","speaker":"陈天中","vi":"Cô ấy cũng là người Thái Lan."}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong bài, khi 安妮 hỏi \"这是谁？\" (Đây là ai?), 陈天中 trả lời \"这是我女朋友。\" (Đây là bạn gái của mình), nên người trong ảnh là 陈天中的女朋友.","options":["安妮","白家月","王老师","陈天中的女朋友"],"q":"陈天中手机里的照片是谁？"},{"answerIdx":0,"explanation":"Trong bài có câu 陈天中 nói \"她也是泰国人。\" (Cô ấy cũng là người Thái Lan); từ 也 (cũng) cho thấy bản thân Trần Thiên Trung cũng là người Thái Lan, nên đáp án đúng là 陈天中也是泰国人.","options":["陈天中也是泰国人","陈天中的女朋友不是泰国人","照片里的人是安妮","陈天中不知道女朋友是哪国人"],"q":"从“她也是泰国人”这句话，我们能知道什么？"}],"scene":"在教室里，下课后，安妮在看陈天中手机里的照片。","sceneVi":"Trong phòng học, sau giờ học, An Ni đang xem ảnh trong điện thoại của Trần Thiên Trung."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"喂，一飞！","pinyin":"Wèi, Yīfēi!","speaker":"王一雪","vi":"A lô, Nhất Phi!"},{"hanzi":"姐姐！","pinyin":"Jiějie!","speaker":"王一飞","vi":"Chị ơi!"},{"hanzi":"你工作还忙吗？","pinyin":"Nǐ gōngzuò hái máng ma?","speaker":"王一雪","vi":"Công việc của em vẫn bận chứ?"},{"hanzi":"对，还很忙。你也很忙吗？","pinyin":"Duì, hái hěn máng. Nǐ yě hěn máng ma?","speaker":"王一飞","vi":"Vâng, vẫn rất bận ạ. Chị cũng rất bận phải không?"},{"hanzi":"我不太忙。我们很想你。","pinyin":"Wǒ bú tài máng. Wǒmen hěn xiǎng nǐ.","speaker":"王一雪","vi":"Chị không bận lắm. Cả nhà rất nhớ em."},{"hanzi":"我也想你们。","pinyin":"Wǒ yě xiǎng nǐmen.","speaker":"王一飞","vi":"Em cũng nhớ mọi người."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi Vương Nhất Tuyết hỏi \"你工作还忙吗？\" (Công việc của em vẫn bận chứ?), Vương Nhất Phi trả lời \"对，还很忙。\" (Vâng, vẫn rất bận), nên đáp án đúng là 很忙.","options":["不太忙","很忙","不工作","不忙"],"q":"王一飞现在工作怎么样？"},{"answerIdx":2,"explanation":"Trong bài có câu 王一雪 nói \"我不太忙。我们很想你。\" (Chị không bận lắm. Mọi người rất nhớ em), nên thông tin đúng là 她不太忙，而且很想王一飞.","options":["她是王一飞的妹妹","她工作很忙","她不太忙，而且很想王一飞","她不想王一飞"],"q":"关于王一雪，下面哪句话是对的？"}],"scene":"在家里，王一雪给王一飞打视频电话。","sceneVi":"Ở nhà, Vương Nhất Tuyết gọi điện thoại video cho Vương Nhất Phi."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (绕口令)","lines":[{"hanzi":"四是四，十是十。","pinyin":"Sì shì sì, shí shì shí.","speaker":"绕口令","vi":"Bốn là bốn, mười là mười."},{"hanzi":"十四是十四，四十是四十。","pinyin":"Shísì shì shísì, sìshí shì sìshí.","speaker":"绕口令","vi":"Mười bốn là mười bốn, bốn mươi là bốn mươi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài đọc líu lưỡi chỉ nhắc đến bốn con số là \"四\" (4), \"十\" (10), \"十四\" (14) và \"四十\" (40), không có số 七 (7), nên đáp án đúng là 七.","options":["四","十","七","四十"],"q":"这个绕口令里没有下面哪个数字？"},{"answerIdx":1,"explanation":"Trong bài có câu \"十四是十四，四十是四十。\" (Mười bốn là mười bốn, bốn mươi là bốn mươi), nên đáp án đúng là 十四是十四，四十是四十.","options":["十四是四十，四十是十四","十四是十四，四十是四十","十四是四，四十是十","四是十四，十是四十"],"q":"“十四”和“四十”在这个绕口令里是怎么说的？"}],"scene":"跟读绕口令。","sceneVi":"Luyện đọc theo bài nói líu lưỡi (Tongue Twister)."}],"hsk1-4":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"一飞忙吗？","pinyin":"Yīfēi máng ma?","speaker":"刘明","vi":"Nhất Phi có bận không?"},{"hanzi":"她很忙。","pinyin":"Tā hěn máng.","speaker":"王一雪","vi":"Cô ấy rất bận."},{"hanzi":"她有多少个学生？","pinyin":"Tā yǒu duōshao gè xuéshēng?","speaker":"刘明","vi":"Cô ấy có bao nhiêu học sinh?"},{"hanzi":"她有二十个学生。","pinyin":"Tā yǒu èrshí gè xuéshēng.","speaker":"王一雪","vi":"Cô ấy có hai mươi học sinh."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu 王一雪 trả lời \"她有二十个学生。\" (Em ấy có hai mươi học sinh), nên đáp án đúng là 二十个.","options":["十二个","二十个","五个","四个"],"q":"王一飞有多少个学生？"},{"answerIdx":0,"explanation":"Trong bài, Lưu Minh mở đầu bằng câu hỏi \"一飞忙吗？\" (Nhất Phi có bận không?) và tiếp tục hỏi về số học sinh của Nhất Phi, nên hai người đang trò chuyện về 王一飞.","options":["王一飞","杨同乐","陈天中","李文"],"q":"刘明和王一雪在聊谁？"}],"scene":"在家里，刘明和王一雪在聊天儿。","sceneVi":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"我有两个哥哥，你呢？","pinyin":"Wǒ yǒu liǎng gè gēge, nǐ ne?","speaker":"王一雪","vi":"Tôi có hai anh trai, còn bạn thì sao?"},{"hanzi":"我没有哥哥。","pinyin":"Wǒ méiyǒu gēge.","speaker":"杨同乐","vi":"Tôi không có anh trai."},{"hanzi":"你家有几口人？","pinyin":"Nǐ jiā yǒu jǐ kǒu rén?","speaker":"王一雪","vi":"Nhà bạn có mấy người?"},{"hanzi":"我家有四口人，爸爸、妈妈、妹妹和我。","pinyin":"Wǒ jiā yǒu sì kǒu rén, bàba, māma, mèimei hé wǒ.","speaker":"杨同乐","vi":"Nhà tôi có bốn người: bố, mẹ, em gái và tôi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu 王一雪 nói \"我有两个哥哥，你呢？\" (Tôi có hai người anh trai, còn bạn thì sao?), nên đáp án đúng là 两个哥哥.","options":["没有哥哥","一个哥哥","两个哥哥","三个哥哥"],"q":"王一雪有几个哥哥？"},{"answerIdx":3,"explanation":"Trong bài có câu 杨同乐 trả lời \"我家有四口人，爸爸、妈妈、妹妹和我。\" (Nhà tôi có bốn người: bố, mẹ, em gái và tôi), nên đáp án đúng là 四口人：爸爸、妈妈、妹妹和他.","options":["三口人：爸爸、妈妈和他","四口人：爸爸、妈妈、哥哥和他","五口人：爸爸、妈妈、哥哥、妹妹和他","四口人：爸爸、妈妈、妹妹和他"],"q":"杨同乐家有几口人？都有谁？"}],"scene":"在公司里，王一雪和杨同乐休息时聊天儿。","sceneVi":"Ở công ty, Vương Nhất Tuyết và Dương Đồng Nhạc trò chuyện lúc nghỉ giải lao."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"这是您儿子吗？","pinyin":"Zhè shì nín érzi ma?","speaker":"杨同乐","vi":"Đây là con trai của chị phải không?"},{"hanzi":"是的。我有两个孩子，一个儿子，一个女儿。","pinyin":"Shì de. Wǒ yǒu liǎng gè háizi, yí gè érzi, yí gè nǚ'ér.","speaker":"王一雪","vi":"Đúng vậy. Tôi có hai người con, một con trai, một con gái."},{"hanzi":"您儿子几岁？","pinyin":"Nín érzi jǐ suì?","speaker":"杨同乐","vi":"Con trai chị mấy tuổi rồi?"},{"hanzi":"他今年五岁。","pinyin":"Tā jīnnián wǔ suì.","speaker":"王一雪","vi":"Cháu năm nay năm tuổi."},{"hanzi":"您女儿多大？","pinyin":"Nín nǚ'ér duō dà?","speaker":"杨同乐","vi":"Con gái chị bao nhiêu tuổi rồi?"},{"hanzi":"她今年十二。","pinyin":"Tā jīnnián shí'èr.","speaker":"王一雪","vi":"Cháu năm nay mười hai tuổi."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, khi Dương Đồng Nhạc hỏi \"您儿子几岁？\" (Con trai chị mấy tuổi?), Vương Nhất Tuyết đáp \"他今年五岁。\" (Cháu năm nay năm tuổi), nên đáp án đúng là 五岁.","options":["五岁","四岁","十二岁","两岁"],"q":"王一雪的儿子今年几岁？"},{"answerIdx":2,"explanation":"Trong bài có hai câu 王一雪 nói \"我有两个孩子，一个儿子，一个女儿。\" (Tôi có hai con, một trai một gái) và \"她今年十二。\" (Cháu gái năm nay mười hai tuổi), nên đáp án đúng là 她有一个儿子和一个女儿，女儿十二岁.","options":["她只有一个儿子，没有女儿","她有两个儿子，今年都五岁","她有一个儿子和一个女儿，女儿十二岁","她的女儿五岁，儿子十二岁"],"q":"关于王一雪的孩子，下面哪句话是对的？"}],"scene":"在街上，王一雪带着儿子偶遇杨同乐。","sceneVi":"Trên đường, Vương Nhất Tuyết dắt con trai tình cờ gặp Dương Đồng Nhạc."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"王一飞很忙，她有二十个学生。","pinyin":"Wáng Yīfēi hěn máng, tā yǒu èrshí gè xuéshēng.","speaker":"Đoạn văn","vi":"Vương Nhất Phi rất bận, cô ấy có hai mươi học sinh."},{"hanzi":"王一雪有两个哥哥，还有两个孩子，一个儿子，一个女儿。","pinyin":"Wáng Yīxuě yǒu liǎng gè gēge, hái yǒu liǎng gè háizi, yí gè érzi, yí gè nǚ'ér.","speaker":"Đoạn văn","vi":"Vương Nhất Tuyết có hai anh trai, còn có hai người con, một con trai và một con gái."},{"hanzi":"她的儿子今年五岁，女儿今年十二岁。","pinyin":"Tā de érzi jīnnián wǔ suì, nǚ'ér jīnnián shí'èr suì.","speaker":"Đoạn văn","vi":"Con trai của chị ấy năm nay năm tuổi, con gái năm nay mười hai tuổi."},{"hanzi":"杨同乐没有哥哥，他家有四口人：爸爸、妈妈、妹妹和他。","pinyin":"Yáng Tónglè méiyǒu gēge, tā jiā yǒu sì kǒu rén: bàba, māma, mèimei hé tā.","speaker":"Đoạn văn","vi":"Dương Đồng Nhạc không có anh trai, nhà anh ấy có bốn người: bố, mẹ, em gái và anh ấy."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong đoạn văn có câu \"王一雪有两个哥哥，还有两个孩子，一个儿子，一个女儿。\" (Vương Nhất Tuyết có hai anh trai và còn có hai người con, một trai một gái), nên đáp án đúng là 王一雪.","options":["王一飞","王一雪","杨同乐","杨同乐的妹妹"],"q":"短文里，谁既有哥哥又有孩子？"},{"answerIdx":3,"explanation":"Trong đoạn văn có câu \"杨同乐没有哥哥，他家有四口人：爸爸、妈妈、妹妹和他。\" (Dương Đồng Nhạc không có anh trai, nhà anh ấy có bốn người: bố, mẹ, em gái và anh ấy), nên đáp án đúng là 杨同乐没有哥哥，他有一个妹妹.","options":["王一飞有十二个学生","王一雪的儿子比女儿大","杨同乐有一个哥哥和一个妹妹","杨同乐没有哥哥，他有一个妹妹"],"q":"根据短文，下面哪句话是对的？"}],"scene":"短文总结第四课课文一至课文三的内容。","sceneVi":"Đoạn văn tổng hợp nội dung Bài khóa 1 đến Bài khóa 3 của Bài 4."}],"hsk1-5":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"今天几号？","pinyin":"Jīntiān jǐ hào?","speaker":"王一雪","vi":"Hôm nay ngày mấy?"},{"hanzi":"今天9月8号。","pinyin":"Jīntiān jiǔ yuè bā hào.","speaker":"刘明","vi":"Hôm nay ngày 8 tháng 9."},{"hanzi":"星期几？","pinyin":"Xīngqī jǐ?","speaker":"王一雪","vi":"Thứ mấy?"},{"hanzi":"星期日。今天我休息。","pinyin":"Xīngqīrì. Jīntiān wǒ xiūxi.","speaker":"刘明","vi":"Chủ nhật. Hôm nay tôi nghỉ."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu “今天9月8号。” (Hôm nay là ngày 8 tháng 9), nên đáp án đúng là 9月8号。","options":["9月8号","9月7号","8月9号","10月8号"],"q":"今天是几月几号？"},{"answerIdx":1,"explanation":"Trong bài Lưu Minh nói “星期日。今天我休息。” (Chủ nhật. Hôm nay tôi nghỉ), nên lý do anh ấy được nghỉ là vì hôm nay là Chủ nhật (因为今天是星期日)。","options":["因为今天是星期一","因为今天是星期日","因为今天他去医院","因为今天他做饭"],"q":"今天刘明为什么休息？"}],"scene":"在家里，刘明和王一雪在聊天儿。","sceneVi":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你会做饭吗？","pinyin":"Nǐ huì zuò fàn ma?","speaker":"王一雪","vi":"Bạn biết nấu ăn không?"},{"hanzi":"我会做。","pinyin":"Wǒ huì zuò.","speaker":"杨同乐","vi":"Tôi biết nấu."},{"hanzi":"你会做什么？","pinyin":"Nǐ huì zuò shénme?","speaker":"王一雪","vi":"Bạn biết nấu món gì?"},{"hanzi":"我会做面条儿、饺子，也会做一些菜。星期天我也做饭。","pinyin":"Wǒ huì zuò miàntiáor, jiǎozi, yě huì zuò yìxiē cài. Xīngqītiān wǒ yě zuò fàn.","speaker":"杨同乐","vi":"Tôi biết làm mì sợi, sủi cảo, cũng biết nấu một số món ăn. Chủ nhật tôi cũng nấu cơm."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Dương Đồng Nhạc nói “我会做面条儿、饺子，也会做一些菜。” (Tôi biết làm mì sợi, sủi cảo và cũng biết nấu một ít món ăn), nên đáp án đúng là 面条儿、饺子和一些菜。","options":["水果和茶","面条儿、饺子和一些菜","米饭和咖啡","他不会做饭"],"q":"杨同乐会做什么？"},{"answerIdx":3,"explanation":"Trong bài có câu “星期天我也做饭。” (Chủ nhật tôi cũng nấu cơm), nên đáp án đúng là 星期天。","options":["星期一","星期三","星期五","星期天"],"q":"杨同乐什么时候也做饭？"}],"scene":"在公司里，王一雪和杨同乐休息时聊天儿。","sceneVi":"Ở công ty, Vương Nhất Tuyết và Dương Đồng Nhạc trò chuyện lúc nghỉ ngơi."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"同乐，下班吗？","pinyin":"Tónglè, xiàbān ma?","speaker":"王一雪","vi":"Đồng Nhạc, tan làm à?"},{"hanzi":"下班。","pinyin":"Xiàbān.","speaker":"杨同乐","vi":"Tan làm rồi."},{"hanzi":"这是你的新电脑吗？","pinyin":"Zhè shì nǐ de xīn diànnǎo ma?","speaker":"王一雪","vi":"Đây là máy tính mới của bạn à?"},{"hanzi":"是的，是我的新电脑。","pinyin":"Shì de, shì wǒ de xīn diànnǎo.","speaker":"杨同乐","vi":"Đúng vậy, là máy tính mới của tôi."},{"hanzi":"真好看！","pinyin":"Zhēn hǎokàn!","speaker":"王一雪","vi":"Đẹp thật đấy!"},{"hanzi":"我也很喜欢它。","pinyin":"Wǒ yě hěn xǐhuan tā.","speaker":"杨同乐","vi":"Tôi cũng rất thích nó."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài Vương Nhất Tuyết khen “真好看！” (Đẹp thật đấy!), nên đáp án đúng là 真好看。","options":["真好看","不好看","很小","很贵"],"q":"王一雪觉得杨同乐的新电脑怎么样？"},{"answerIdx":1,"explanation":"Trong bài Dương Đồng Nhạc nói “我也很喜欢它。” (Tôi cũng rất thích nó), nên đáp án đúng là 很喜欢。","options":["不喜欢","很喜欢","没说喜不喜欢","觉得不好看"],"q":"杨同乐喜欢这个新电脑吗？"}],"scene":"在公司里，王一雪和杨同乐下班时聊天儿。","sceneVi":"Ở công ty, Vương Nhất Tuyết và Dương Đồng Nhạc trò chuyện lúc tan làm."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"今天9月8号，星期日，刘明在家里休息。","pinyin":"Jīntiān jiǔ yuè bā hào, Xīngqīrì, Liú Míng zài jiā li xiūxi.","speaker":"Đoạn văn","vi":"Hôm nay là ngày 8 tháng 9, Chủ nhật, Lưu Minh nghỉ ngơi ở nhà."},{"hanzi":"杨同乐会做面条儿、饺子，也会做一些菜，星期天他也做饭。","pinyin":"Yáng Tónglè huì zuò miàntiáor, jiǎozi, yě huì zuò yìxiē cài, Xīngqītiān tā yě zuò fàn.","speaker":"Đoạn văn","vi":"Dương Đồng Nhạc biết làm mì sợi, sủi cảo, cũng biết nấu một số món ăn, Chủ nhật anh ấy cũng nấu cơm."},{"hanzi":"下班时，王一雪和杨同乐聊天儿。","pinyin":"Xiàbān shí, Wáng Yīxuě hé Yáng Tónglè liáotiānr.","speaker":"Đoạn văn","vi":"Lúc tan làm, Vương Nhất Tuyết và Dương Đồng Nhạc trò chuyện."},{"hanzi":"杨同乐有一个新电脑，这个电脑真好看，他也很喜欢它。","pinyin":"Yáng Tónglè yǒu yí gè xīn diànnǎo, zhège diànnǎo zhēn hǎokàn, tā yě hěn xǐhuan tā.","speaker":"Đoạn văn","vi":"Dương Đồng Nhạc có một chiếc máy tính mới, chiếc máy tính này đẹp thật, anh ấy cũng rất thích nó."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong đoạn văn có câu “今天9月8号，星期日，刘明在家里休息。” (Hôm nay là Chủ nhật ngày 8 tháng 9, Lưu Minh nghỉ ngơi ở nhà), nên đáp án đúng là 刘明。","options":["王一雪","杨同乐","刘明","王一雪和杨同乐"],"q":"9月8号星期日，谁在家里休息？"},{"answerIdx":3,"explanation":"Trong đoạn văn có câu “杨同乐有一个新电脑” (Dương Đồng Nhạc có một chiếc máy tính mới), nên đáp án đúng là 新电脑。","options":["新手机","新书","新桌子","新电脑"],"q":"杨同乐有什么新东西？"}],"scene":"复习第五课的三篇课文。","sceneVi":"Tổng hợp nội dung ba bài khóa của Bài 5."}],"hsk1-6":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月，你的手机号是多少？","pinyin":"Jiāyuè, nǐ de shǒujīhào shì duōshao?","speaker":"李文","vi":"Gia Nguyệt, số điện thoại di động của bạn là bao nhiêu?"},{"hanzi":"我的手机号是+33 601493190。","pinyin":"Wǒ de shǒujīhào shì sān sān liù líng yāo sì jiǔ sān yāo jiǔ líng.","speaker":"白家月","vi":"Số điện thoại của tôi là +33 601493190."},{"hanzi":"我的手机号是+86 13552721160。","pinyin":"Wǒ de shǒujīhào shì bā liù yāo sān wǔ wǔ èr qī èr yāo yāo liù líng.","speaker":"李文","vi":"Số điện thoại của tôi là +86 13552721160."},{"hanzi":"好的。","pinyin":"Hǎo de.","speaker":"白家月","vi":"Được rồi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Bạch Gia Nguyệt nói “我的手机号是+33 601493190。” (Số điện thoại di động của tôi là +33 601493190), nên đáp án đúng là +33 601493190。","options":["+86 13552721160","+33 601493190","+33 13552721160","+86 601493190"],"q":"白家月的手机号是多少？"},{"answerIdx":0,"explanation":"Trong bài, Lý Văn hỏi số điện thoại của Bạch Gia Nguyệt (“家月，你的手机号是多少？”) và cũng nói ra số điện thoại của mình (“我的手机号是+86 13552721160。”), nên đáp án đúng là 问白家月的手机号，也说了自己的手机号。","options":["问白家月的手机号，也说了自己的手机号","问白家月去不去医院","和白家月一起买东西","问白家月会做什么菜"],"q":"对话里，李文做了什么？"}],"scene":"在校园里，李文向白家月要手机号。","sceneVi":"Trong khuôn viên trường, Lý Văn hỏi xin số điện thoại di động của Bạch Gia Nguyệt."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"家月，明天你去哪儿？","pinyin":"Jiāyuè, míngtiān nǐ qù nǎr?","speaker":"陈天中","vi":"Gia Nguyệt, ngày mai bạn đi đâu?"},{"hanzi":"我想去超市买东西。","pinyin":"Wǒ xiǎng qù chāoshì mǎi dōngxi.","speaker":"白家月","vi":"Tôi muốn đi siêu thị mua đồ."},{"hanzi":"你去超市买什么？","pinyin":"Nǐ qù chāoshì mǎi shénme?","speaker":"陈天中","vi":"Bạn đi siêu thị mua gì?"},{"hanzi":"我想买些牛奶。","pinyin":"Wǒ xiǎng mǎi xiē niúnǎi.","speaker":"白家月","vi":"Tôi muốn mua một ít sữa bò."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài Trần Thiên Trung hỏi “家月，明天你去哪儿？” (Gia Nguyệt, ngày mai bạn đi đâu?) và Bạch Gia Nguyệt đáp “我想去超市买东西。” (Tôi muốn đi siêu thị mua đồ), nên đáp án đúng là 明天。","options":["今天","昨天","明天","星期天"],"q":"白家月什么时候想去超市？"},{"answerIdx":2,"explanation":"Trong bài Bạch Gia Nguyệt nói “我想买些牛奶。” (Tôi muốn mua một ít sữa bò), nên đáp án đúng là 牛奶。","options":["茶","米饭","牛奶","包子"],"q":"白家月想去超市买什么？"}],"scene":"在教室里，下课后，白家月和陈天中在聊天儿。","sceneVi":"Trong phòng học, sau giờ tan học, Bạch Gia Nguyệt và Trần Thiên Trung đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"星期天我们去哪儿吃晚饭？","pinyin":"Xīngqītiān wǒmen qù nǎr chī wǎnfàn?","speaker":"王一雪","vi":"Chủ nhật chúng ta đi đâu ăn tối?"},{"hanzi":"我还想去西安饭店。","pinyin":"Wǒ hái xiǎng qù Xī’ān Fàndiàn.","speaker":"刘明","vi":"Anh vẫn muốn đến Nhà hàng Tây An."},{"hanzi":"那边的包子非常好吃，我想吃包子。","pinyin":"Nàbiān de bāozi fēicháng hǎochī, wǒ xiǎng chī bāozi.","speaker":"刘小雪","vi":"Bánh bao ở bên đó rất ngon, con muốn ăn bánh bao."},{"hanzi":"妈妈，我想吃米饭，不想吃包子。","pinyin":"Māma, wǒ xiǎng chī mǐfàn, bù xiǎng chī bāozi.","speaker":"刘小明","vi":"Mẹ ơi, con muốn ăn cơm, không muốn ăn bánh bao."},{"hanzi":"好的。我们怎么去？","pinyin":"Hǎo de. Wǒmen zěnme qù?","speaker":"王一雪","vi":"Được thôi. Chúng ta đi bằng cách nào?"},{"hanzi":"坐出租车去。","pinyin":"Zuò chūzūchē qù.","speaker":"刘明","vi":"Đi bằng taxi."}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong bài Lưu Tiểu Minh nói “妈妈，我想吃米饭，不想吃包子。” (Mẹ ơi, con muốn ăn cơm, không muốn ăn bánh bao), nên đáp án đúng là 刘小明。","options":["王一雪","刘明","刘小雪","刘小明"],"q":"谁想吃米饭，不想吃包子？"},{"answerIdx":0,"explanation":"Trong bài Lưu Minh nói “坐出租车去。” (Đi bằng xe taxi), nên đáp án đúng là 坐出租车去。","options":["坐出租车去","坐公共汽车去","走路去","坐火车去"],"q":"他们怎么去西安饭店？"}],"scene":"在家里，王一雪全家在讨论周末晚餐安排。","sceneVi":"Ở nhà, cả gia đình Vương Nhất Tuyết đang bàn kế hoạch ăn tối cuối tuần."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"在校园里，白家月的手机号是+33 601493190，李文的手机号是+86 13552721160。","pinyin":"Zài xiàoyuán li, Bái Jiāyuè de shǒujīhào shì sān sān liù líng yāo sì jiǔ sān yāo jiǔ líng, Lǐ Wén de shǒujīhào shì bā liù yāo sān wǔ wǔ èr qī èr yāo yāo liù líng.","speaker":"Đoạn văn","vi":"Trong khuôn viên trường, số điện thoại di động của Bạch Gia Nguyệt là +33 601493190, số điện thoại của Lý Văn là +86 13552721160."},{"hanzi":"下课后，在教室里，白家月和陈天中聊天儿，明天白家月想去超市买些牛奶。","pinyin":"Xiàkè hòu, zài jiàoshì li, Bái Jiāyuè hé Chén Tiānzhōng liáotiānr, míngtiān Bái Jiāyuè xiǎng qù chāoshì mǎi xiē niúnǎi.","speaker":"Đoạn văn","vi":"Sau giờ tan học, trong phòng học, Bạch Gia Nguyệt và Trần Thiên Trung trò chuyện, ngày mai Bạch Gia Nguyệt muốn đi siêu thị mua một ít sữa bò."},{"hanzi":"在家里，王一雪和刘明星期天想去西安饭店吃晚饭。","pinyin":"Zài jiā li, Wáng Yīxuě hé Liú Míng Xīngqītiān xiǎng qù Xī’ān Fàndiàn chī wǎnfàn.","speaker":"Đoạn văn","vi":"Ở nhà, Vương Nhất Tuyết và Lưu Minh muốn đến Nhà hàng Tây An ăn tối vào Chủ nhật."},{"hanzi":"刘小雪想吃那边的包子，刘小明想吃米饭，他们坐出租车去。","pinyin":"Liú Xiǎoxuě xiǎng chī nàbiān de bāozi, Liú Xiǎomíng xiǎng chī mǐfàn, tāmen zuò chūzūchē qù.","speaker":"Đoạn văn","vi":"Lưu Tiểu Tuyết muốn ăn bánh bao ở bên đó, Lưu Tiểu Minh muốn ăn cơm, họ đi bằng taxi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong đoạn văn có câu “明天白家月想去超市买些牛奶。” (Ngày mai Bạch Gia Nguyệt muốn đi siêu thị mua một ít sữa bò), nên đáp án đúng là 去超市买牛奶。","options":["去教室上课","去西安饭店吃晚饭","去超市买牛奶","在家里看书"],"q":"明天白家月想去哪儿做什么？"},{"answerIdx":0,"explanation":"Trong đoạn văn có câu “王一雪和刘明星期天想去西安饭店吃晚饭。” và “他们坐出租车去。” (Chủ nhật Vương Nhất Tuyết và Lưu Minh muốn đến Nhà hàng Tây An ăn tối và họ đi bằng taxi), nên đáp án đúng là 去西安饭店，坐出租车去。","options":["去西安饭店，坐出租车去","去超市，坐出租车去","去西安饭店，坐公共汽车去","在家里吃，不去饭店"],"q":"王一雪和家人星期天去哪儿吃晚饭，怎么去？"}],"scene":"复习第六课的三篇课文。","sceneVi":"Tổng hợp nội dung ba bài khóa của Bài 6."}],"hsk1-7":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"现在几点？","pinyin":"Xiànzài jǐ diǎn?","speaker":"白家月","vi":"Bây giờ mấy giờ rồi?"},{"hanzi":"早上八点四十。","pinyin":"Zǎoshang bā diǎn sìshí.","speaker":"安妮","vi":"8 giờ 40 phút sáng."},{"hanzi":"我上午十点十分有课。","pinyin":"Wǒ shàngwǔ shí diǎn shí fēn yǒu kè.","speaker":"白家月","vi":"10 giờ 10 phút sáng nay tôi có tiết học."},{"hanzi":"好的，我们下午两点见吧。","pinyin":"Hǎo de, wǒmen xiàwǔ liǎng diǎn jiàn ba.","speaker":"安妮","vi":"Được, chúng ta gặp nhau lúc 2 giờ chiều nhé."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài An Ni nói “早上八点四十。” (8 giờ 40 sáng), nên đáp án đúng là 早上八点四十。","options":["早上八点四十","上午十点十分","下午两点","晚上六点半"],"q":"现在是几点？"},{"answerIdx":2,"explanation":"Trong bài An Ni nói “好的，我们下午两点见吧。” (Được, chúng ta gặp nhau lúc 2 giờ chiều nhé), nên đáp án đúng là 下午两点。","options":["早上八点四十","上午十点十分","下午两点","下午四点半"],"q":"白家月和安妮几点见？"}],"scene":"白家月和安妮在打电话。","sceneVi":"Bạch Gia Nguyệt và An Ni đang gọi điện thoại."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"下午我想去电影院看电影，你去吗？","pinyin":"Xiàwǔ wǒ xiǎng qù diànyǐngyuàn kàn diànyǐng, nǐ qù ma?","speaker":"李文","vi":"Chiều nay tôi muốn đi rạp chiếu phim xem phim, bạn có đi không?"},{"hanzi":"我不想去，下午还有事。","pinyin":"Wǒ bù xiǎng qù, xiàwǔ hái yǒu shì.","speaker":"白家月","vi":"Tôi không muốn đi, chiều nay tôi vẫn còn việc."},{"hanzi":"好的。明天呢？","pinyin":"Hǎo de. Míngtiān ne?","speaker":"李文","vi":"Được rồi. Thế ngày mai thì sao?"},{"hanzi":"我明天下午两点还上课呢，四点半下课。","pinyin":"Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne, sì diǎn bàn xiàkè.","speaker":"白家月","vi":"2 giờ chiều mai tôi vẫn đang học trên lớp đấy, 4 giờ rưỡi mới tan học."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Lý Văn nói “下午我想去电影院看电影” (Buổi chiều tôi muốn đi rạp chiếu phim xem phim), nên đáp án đúng là 去电影院。","options":["去超市","去电影院","去书店","去医院"],"q":"李文下午想去哪儿？"},{"answerIdx":2,"explanation":"Trong bài Bạch Gia Nguyệt nói “我明天下午两点还上课呢，四点半下课。” (Chiều mai 2 giờ tôi còn lên lớp, 4 giờ rưỡi tan học), nên đáp án đúng là 四点半。","options":["两点","三点半","四点半","六点半"],"q":"白家月明天几点下课？"}],"scene":"在校园里，李文遇到白家月。","sceneVi":"Trong khuôn viên trường, Lý Văn tình cờ gặp Bạch Gia Nguyệt."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"喂，你在哪儿呢？","pinyin":"Wèi, nǐ zài nǎr ne?","speaker":"王一雪","vi":"Alô, anh đang ở đâu thế?"},{"hanzi":"我在家里呢。","pinyin":"Wǒ zài jiā li ne.","speaker":"刘明","vi":"Anh đang ở nhà đây."},{"hanzi":"我晚上六点半下班。","pinyin":"Wǒ wǎnshang liù diǎn bàn xiàbān.","speaker":"王一雪","vi":"Tối nay 6 giờ rưỡi em tan làm."},{"hanzi":"我八点去医院上班。","pinyin":"Wǒ bā diǎn qù yīyuàn shàngbān.","speaker":"刘明","vi":"8 giờ anh đến bệnh viện làm việc."},{"hanzi":"好的，你去店里买些菜吧。","pinyin":"Hǎo de, nǐ qù diàn li mǎi xiē cài ba.","speaker":"王一雪","vi":"Được rồi, anh ra cửa hàng mua một ít rau nhé."},{"hanzi":"好，我十分钟后去。","pinyin":"Hǎo, wǒ shí fēnzhōng hòu qù.","speaker":"刘明","vi":"Được, 10 phút nữa anh đi."}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong bài Lưu Minh trả lời “我在家里呢。” (Anh đang ở nhà đây), nên đáp án đúng là 在家里。","options":["在办公室","在医院","在店里","在家里"],"q":"王一雪打电话时，刘明在哪儿？"},{"answerIdx":1,"explanation":"Trong bài Vương Nhất Tuyết bảo “你去店里买些菜吧。” (Anh ra cửa hàng mua ít rau nhé) và Lưu Minh đáp “好，我十分钟后去。” (Được, 10 phút nữa anh đi), nên đáp án đúng là 去店里买菜。","options":["去医院上班","去店里买菜","去办公室找王一雪","去电影院看电影"],"q":"十分钟后，刘明去哪儿做什么？"}],"scene":"王一雪在办公室给刘明打电话。","sceneVi":"Vương Nhất Tuyết đang ở văn phòng gọi điện thoại cho Lưu Minh."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"现在是早上八点四十，白家月上午十点十分有课，她和安妮下午两点见。","pinyin":"Xiànzài shì zǎoshang bā diǎn sìshí, Bái Jiāyuè shàngwǔ shí diǎn shí fēn yǒu kè, tā hé Ānnī xiàwǔ liǎng diǎn jiàn.","speaker":"Đoạn văn","vi":"Bây giờ là 8 giờ 40 sáng, Bạch Gia Nguyệt có tiết học lúc 10 giờ 10 sáng, cô ấy và An Ni gặp nhau lúc 2 giờ chiều."},{"hanzi":"下午李文想去电影院看电影，白家月不想去，她下午还有事，明天下午两点还上课，四点半下课。","pinyin":"Xiàwǔ Lǐ Wén xiǎng qù diànyǐngyuàn kàn diànyǐng, Bái Jiāyuè bù xiǎng qù, tā xiàwǔ hái yǒu shì, míngtiān xiàwǔ liǎng diǎn hái shàngkè, sì diǎn bàn xiàkè.","speaker":"Đoạn văn","vi":"Chiều nay Lý Văn muốn đi rạp chiếu phim xem phim, Bạch Gia Nguyệt không muốn đi, chiều nay cô ấy vẫn còn việc, chiều mai 2 giờ vẫn học trên lớp, 4 giờ rưỡi tan học."},{"hanzi":"王一雪晚上六点半下班，刘明在家呢，他八点去医院上班。","pinyin":"Wáng Yīxuě wǎnshang liù diǎn bàn xiàbān, Liú Míng zài jiā ne, tā bā diǎn qù yīyuàn shàngbān.","speaker":"Đoạn văn","vi":"Vương Nhất Tuyết 6 giờ rưỡi tối tan làm, Lưu Minh đang ở nhà, 8 giờ anh ấy đến bệnh viện làm việc."},{"hanzi":"刘明十分钟后去店里买些菜。","pinyin":"Liú Míng shí fēnzhōng hòu qù diàn li mǎi xiē cài.","speaker":"Đoạn văn","vi":"Mười phút nữa Lưu Minh sẽ ra cửa hàng mua một ít rau."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong đoạn văn có câu “明天下午两点还上课，四点半下课。” (Chiều mai 2 giờ còn học, 4 giờ rưỡi tan học), nên đáp án đúng là 四点半。","options":["两点","四点半","六点半","十点十分"],"q":"白家月明天下午几点下课？"},{"answerIdx":3,"explanation":"Trong đoạn văn có câu “刘明在家呢，他八点去医院上班。” (Lưu Minh đang ở nhà, 8 giờ anh ấy đến bệnh viện làm việc), nên đáp án đúng là 刘明。","options":["王一雪","白家月","李文","刘明"],"q":"谁晚上八点去医院上班？"}],"scene":"综合课文一到课文三的时间与日程。","sceneVi":"Tổng hợp thời gian và lịch trình từ Bài khóa 1 đến Bài khóa 3."}],"hsk1-8":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"房间外有一只小猫。","pinyin":"Fángjiān wài yǒu yì zhī xiǎo māo.","speaker":"白家月","vi":"Ngoài phòng có một chú mèo con."},{"hanzi":"我没看见，它在哪儿呢？","pinyin":"Wǒ méi kànjiàn, tā zài nǎr ne?","speaker":"陈天中","vi":"Tôi không thấy, nó ở đâu thế?"},{"hanzi":"它在桌子下呢。","pinyin":"Tā zài zhuōzi xià ne.","speaker":"白家月","vi":"Nó ở dưới gầm bàn đấy."},{"hanzi":"这只小猫真漂亮！","pinyin":"Zhè zhī xiǎo māo zhēn piàoliang!","speaker":"陈天中","vi":"Chú mèo con này thật xinh đẹp!"}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài Bạch Gia Nguyệt nói “房间外有一只小猫。” (Ngoài phòng có một chú mèo con) và “它在桌子下呢。” (Nó ở dưới cái bàn), nên đáp án đúng là 在房间外桌子下。","options":["在房间里","在桌子上","在房间外桌子下","在椅子上"],"q":"小猫在哪儿？"},{"answerIdx":0,"explanation":"Trong bài Trần Thiên Trung khen “这只小猫真漂亮！” (Chú mèo con này thật xinh đẹp!), nên đáp án đúng là 真漂亮。","options":["真漂亮","很大","不可爱","很胖"],"q":"陈天中觉得这只小猫怎么样？"}],"scene":"在王一飞家，白家月和陈天中来做客。","sceneVi":"Tại nhà Vương Nhất Phi, Bạch Gia Nguyệt và Trần Thiên Trung đến chơi."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"我们在哪儿见呢？","pinyin":"Wǒmen zài nǎr jiàn ne?","speaker":"白家月","vi":"Chúng ta gặp nhau ở đâu nhé?"},{"hanzi":"在学校书店前见吧。","pinyin":"Zài xuéxiào shūdiàn qián jiàn ba.","speaker":"李文","vi":"Gặp nhau ở trước hiệu sách của trường nhé."},{"hanzi":"好的。下午两点你能到吗？","pinyin":"Hǎo de. Xiàwǔ liǎng diǎn nǐ néng dào ma?","speaker":"白家月","vi":"Được rồi. 2 giờ chiều bạn có đến được không?"},{"hanzi":"我能到。我在学校吃午饭。","pinyin":"Wǒ néng dào. Wǒ zài xuéxiào chī wǔfàn.","speaker":"李文","vi":"Tôi đến được. Tôi ăn cơm trưa ở trường."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Lý Văn nói “在学校书店前见吧。” (Gặp nhau trước hiệu sách của trường nhé), nên đáp án đúng là 在学校书店前。","options":["在教室里","在学校书店前","在电影院前","在饭店里"],"q":"白家月和李文在哪儿见？"},{"answerIdx":2,"explanation":"Trong bài Lý Văn nói “我在学校吃午饭。” (Tôi ăn cơm trưa ở trường), nên đáp án đúng là 在学校。","options":["在家里","在书店里","在学校","在饭店"],"q":"李文在哪儿吃午饭？"}],"scene":"在教室里，下课后，白家月给李文打电话。","sceneVi":"Trong lớp học, sau khi tan học, Bạch Gia Nguyệt gọi điện thoại cho Lý Văn."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"小胡，还没吃饭呢？","pinyin":"Xiǎo Hú, hái méi chī fàn ne?","speaker":"刘明","vi":"Tiểu Hồ, vẫn chưa ăn cơm à?"},{"hanzi":"没吃呢。","pinyin":"Méi chī ne.","speaker":"胡医生","vi":"Vẫn chưa ăn ạ."},{"hanzi":"大医院病人多，医生非常忙。","pinyin":"Dà yīyuàn bìngrén duō, yīshēng fēicháng máng.","speaker":"刘明","vi":"Bệnh viện lớn nhiều bệnh nhân, bác sĩ vô cùng bận."},{"hanzi":"是的。我爸爸也在医院工作，他也非常忙。","pinyin":"Shì de. Wǒ bàba yě zài yīyuàn gōngzuò, tā yě fēicháng máng.","speaker":"胡医生","vi":"Đúng vậy. Bố tôi cũng làm việc ở bệnh viện, ông ấy cũng rất bận."},{"hanzi":"你家有两个医生？","pinyin":"Nǐ jiā yǒu liǎng gè yīshēng?","speaker":"刘明","vi":"Nhà cậu có hai bác sĩ à?"},{"hanzi":"对。","pinyin":"Duì.","speaker":"胡医生","vi":"Đúng ạ."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Lưu Minh nói “大医院病人多，医生非常忙。” (Bệnh viện lớn bệnh nhân đông, bác sĩ vô cùng bận rộn), nên đáp án đúng là 因为大医院病人多。","options":["因为大医院医生少","因为大医院病人多","因为医生不想吃饭","因为医生都在家里"],"q":"为什么大医院的医生非常忙？"},{"answerIdx":1,"explanation":"Trong bài Lưu Minh hỏi “你家有两个医生？” (Nhà anh có hai bác sĩ à?) và bác sĩ Hồ đáp “对。” (Đúng vậy), nên đáp án đúng là 两个。","options":["一个","两个","三个","四个"],"q":"胡医生家有几个医生？"}],"scene":"在医院里，刘明和同事胡医生在聊天儿。","sceneVi":"Trong bệnh viện, Lưu Minh và đồng nghiệp là bác sĩ Hồ đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"白家月和陈天中在王一飞家做客，房间外桌子下有一只漂亮的小猫。","pinyin":"Bái Jiāyuè hé Chén Tiānzhōng zài Wáng Yīfēi jiā zuòkè, fángjiān wài zhuōzi xià yǒu yì zhī piàoliang de xiǎo māo.","speaker":"Đoạn văn","vi":"Bạch Gia Nguyệt và Trần Thiên Trung đến chơi nhà Vương Nhất Phi, ngoài phòng dưới gầm bàn có một chú mèo con xinh đẹp."},{"hanzi":"下课后，白家月和李文下午两点在学校书店前见，李文在学校吃午饭。","pinyin":"Xiàkè hòu, Bái Jiāyuè hé Lǐ Wén xiàwǔ liǎng diǎn zài xuéxiào shūdiàn qián jiàn, Lǐ Wén zài xuéxiào chī wǔfàn.","speaker":"Đoạn văn","vi":"Sau khi tan học, Bạch Gia Nguyệt và Lý Văn gặp nhau lúc 2 giờ chiều trước hiệu sách của trường, Lý Văn ăn cơm trưa ở trường."},{"hanzi":"在医院里，小胡医生还没吃饭呢，大医院病人多，医生非常忙。","pinyin":"Zài yīyuàn li, Xiǎo Hú yīshēng hái méi chī fàn ne, dà yīyuàn bìngrén duō, yīshēng fēicháng máng.","speaker":"Đoạn văn","vi":"Ở bệnh viện, bác sĩ Tiểu Hồ vẫn chưa ăn cơm, bệnh viện lớn nhiều bệnh nhân nên bác sĩ rất bận."},{"hanzi":"胡医生的爸爸也在医院工作，他家有两个医生。","pinyin":"Hú yīshēng de bàba yě zài yīyuàn gōngzuò, tā jiā yǒu liǎng gè yīshēng.","speaker":"Đoạn văn","vi":"Bố của bác sĩ Hồ cũng làm việc ở bệnh viện, nhà anh ấy có hai bác sĩ."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong đoạn văn có câu “下课后，白家月和李文下午两点在学校书店前见，李文在学校吃午饭。” (Sau giờ học, Bạch Gia Nguyệt và Lý Văn gặp nhau trước hiệu sách trường lúc 2 giờ chiều, Lý Văn ăn cơm trưa ở trường), nên đáp án đúng là 李文。","options":["白家月","陈天中","李文","小胡医生"],"q":"下午两点在学校书店前见，谁在学校吃午饭？"},{"answerIdx":3,"explanation":"Trong đoạn văn có câu “胡医生的爸爸也在医院工作” (Bố của bác sĩ Hồ cũng làm việc ở bệnh viện), nên đáp án đúng là 在医院。","options":["在学校","在书店","在公司","在医院"],"q":"胡医生的爸爸在哪儿工作？"}],"scene":"综合课文一到课文三的地点与工作情况。","sceneVi":"Tổng hợp địa điểm và công việc từ Bài khóa 1 đến Bài khóa 3."}],"hsk1-9":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"学校前边有一家电影院。","pinyin":"Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.","speaker":"李文","vi":"Phía trước trường học có một rạp chiếu phim."},{"hanzi":"对。我们晚上去那个电影院看电影吧。","pinyin":"Duì. Wǒmen wǎnshang qù nàge diànyǐngyuàn kàn diànyǐng ba.","speaker":"白家月","vi":"Đúng vậy. Tối nay chúng ta đến rạp chiếu phim đó xem phim đi."},{"hanzi":"好！我们七点在电影院外边见，好吗？","pinyin":"Hǎo! Wǒmen qī diǎn zài diànyǐngyuàn wàibian jiàn, hǎo ma?","speaker":"李文","vi":"Được! Chúng ta gặp nhau lúc bảy giờ ở bên ngoài rạp chiếu phim nhé?"},{"hanzi":"好的，晚上七点见！","pinyin":"Hǎo de, wǎnshang qī diǎn jiàn!","speaker":"白家月","vi":"Được thôi, hẹn gặp tối nay lúc bảy giờ!"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Lý Văn nói \"学校前边有一家电影院。\" (Phía trước trường học có một rạp chiếu phim.), nên đáp án đúng là 学校前边.","options":["学校前边","学校后边","学校里边","学校外边"],"q":"电影院在哪儿？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我们七点在电影院外边见\" (Chúng ta gặp nhau ở bên ngoài rạp chiếu phim lúc 7 giờ nhé) và \"好的，晚上七点见！\" (Được, tối 7 giờ gặp!), nên đáp án đúng là 七点在电影院外边.","options":["六点在学校外边","七点在电影院里边","七点在电影院外边","八点在学校前边"],"q":"他们晚上几点在哪儿见？"}],"scene":"在校园里，李文和白家月在聊天儿。","sceneVi":"Trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"椅子上有一本中文书，那是谁的书？","pinyin":"Yǐzi shang yǒu yì běn Zhōngwén shū, nà shì shéi de shū?","speaker":"白家月","vi":"Trên ghế có một quyển sách tiếng Trung, đó là sách của ai vậy?"},{"hanzi":"是我的书，谢谢。这是我的第二本中文书。","pinyin":"Shì wǒ de shū, xièxie. Zhè shì wǒ de dì-èr běn Zhōngwén shū.","speaker":"陈天中","vi":"Là sách của tôi, cảm ơn bạn. Đây là quyển sách tiếng Trung thứ hai của tôi."},{"hanzi":"不客气。你明天上午在哪儿？","pinyin":"Bú kèqi. Nǐ míngtiān shàngwǔ zài nǎr?","speaker":"白家月","vi":"Không có gì. Sáng mai bạn ở đâu?"},{"hanzi":"我明天上午在学校学习。","pinyin":"Wǒ míngtiān shàngwǔ zài xuéxiào xuéxí.","speaker":"陈天中","vi":"Sáng mai tôi học ở trường."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt hỏi \"椅子上有一本中文书，那是谁的书？\" (Trên ghế có một quyển sách tiếng Trung, đó là sách của ai?) và Trần Thiên Trung đáp \"是我的书\" (Là sách của tôi), nên đáp án đúng là 一本中文书，是陈天中的.","options":["一本中文书，是白家月的","两本中文书，是陈天中的","一本中文书，是陈天中的","一本中文书，不是陈天中的"],"q":"椅子上有什么？是谁的？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我明天上午在学校学习。\" (Sáng ngày mai tôi học ở trường.), nên đáp án đúng là 在学校学习.","options":["在家里看书","在教室休息","在学校学习","去电影院看电影"],"q":"陈天中明天上午在哪儿做什么？"}],"scene":"在教室里，下课后，白家月和陈天中在对话。","sceneVi":"Trong phòng học, sau khi tan học, Bạch Gia Nguyệt và Trần Thiên Trung đang nói chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"明天星期六，你做什么？","pinyin":"Míngtiān Xīngqīliù, nǐ zuò shénme?","speaker":"王一雪","vi":"Ngày mai là thứ Bảy, bạn làm gì?"},{"hanzi":"我白天在家里读书，晚上和朋友们去外边唱歌。","pinyin":"Wǒ báitiān zài jiā li dúshū, wǎnshang hé péngyoumen qù wàibian chàng gē.","speaker":"杨同乐","vi":"Ban ngày tôi đọc sách ở nhà, buổi tối cùng bạn bè ra ngoài hát."},{"hanzi":"你唱歌很好听。","pinyin":"Nǐ chàng gē hěn hǎotīng.","speaker":"王一雪","vi":"Bạn hát rất hay."},{"hanzi":"谢谢！您星期六做什么？","pinyin":"Xièxie! Nín Xīngqīliù zuò shénme?","speaker":"杨同乐","vi":"Cảm ơn! Thứ Bảy chị làm gì?"},{"hanzi":"我在家里做饭、看电视，和孩子们、小狗玩。","pinyin":"Wǒ zài jiā li zuò fàn, kàn diànshì, hé háizimen, xiǎo gǒu wán.","speaker":"王一雪","vi":"Tôi ở nhà nấu cơm, xem tivi, chơi với các con và chú chó nhỏ."},{"hanzi":"我也有一只小狗。","pinyin":"Wǒ yě yǒu yì zhī xiǎo gǒu.","speaker":"杨同乐","vi":"Tôi cũng có một chú chó nhỏ."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Dương Đồng Nhạc nói \"我白天在家里读书，晚上和朋友们去外边唱歌。\" (Ban ngày tôi đọc sách ở nhà, buổi tối đi ra ngoài hát với bạn bè.), nên đáp án đúng là 白天在家读书，晚上去外边唱歌.","options":["白天在家做饭，晚上看电视","白天在家读书，晚上去外边唱歌","白天去外边唱歌，晚上在家读书","白天和孩子们玩，晚上和朋友吃饭"],"q":"杨同乐星期六做什么？"},{"answerIdx":0,"explanation":"Trong bài, Vương Nhất Tuyết nói ở nhà chơi với \"...小狗玩\" (chơi với chó con) và Dương Đồng Nhạc đáp \"我也有一只小狗。\" (Tôi cũng có một con chó con.), nên đáp án đúng là 都有一只小狗.","options":["都有一只小狗","都有很多孩子","都喜欢星期六在家做饭","都去外边唱歌"],"q":"王一雪和杨同乐都有什么？"}],"scene":"在办公室里，休息时，王一雪和杨同乐谈论周末生活。","sceneVi":"Trong văn phòng, vào giờ nghỉ giải lao, Vương Nhất Tuyết và Dương Đồng Nhạc trò chuyện về cuộc sống cuối tuần."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"学校前边有一家电影院，李文和白家月晚上七点在电影院外边见，去那个电影院看电影。","pinyin":"Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn, Lǐ Wén hé Bái Jiāyuè wǎnshang qī diǎn zài diànyǐngyuàn wàibian jiàn, qù nàge diànyǐngyuàn kàn diànyǐng.","speaker":"Đoạn văn","vi":"Phía trước trường học có một rạp chiếu phim, tối nay lúc 7 giờ Lý Văn và Bạch Gia Nguyệt gặp nhau ở bên ngoài rạp rồi vào rạp đó xem phim."},{"hanzi":"在教室里，椅子上有一本中文书，那是陈天中的第二本中文书，他明天上午在学校学习。","pinyin":"Zài jiàoshì li, yǐzi shang yǒu yì běn Zhōngwén shū, nà shì Chén Tiānzhōng de dì-èr běn Zhōngwén shū, tā míngtiān shàngwǔ zài xuéxiào xuéxí.","speaker":"Đoạn văn","vi":"Trong phòng học, trên ghế có một quyển sách tiếng Trung, đó là quyển sách tiếng Trung thứ hai của Trần Thiên Trung, sáng mai anh ấy học ở trường."},{"hanzi":"明天星期六，杨同乐白天在家里读书，晚上和朋友们去外边唱歌。","pinyin":"Míngtiān Xīngqīliù, Yáng Tónglè báitiān zài jiā li dúshū, wǎnshang hé péngyoumen qù wàibian chàng gē.","speaker":"Đoạn văn","vi":"Ngày mai là thứ Bảy, ban ngày Dương Đồng Nhạc đọc sách ở nhà, buổi tối cùng bạn bè ra ngoài hát."},{"hanzi":"王一雪星期六在家里做饭、看电视，和孩子们、小狗玩，杨同乐也有一只小狗。","pinyin":"Wáng Yīxuě Xīngqīliù zài jiā li zuò fàn, kàn diànshì, hé háizimen, xiǎo gǒu wán, Yáng Tónglè yě yǒu yì zhī xiǎo gǒu.","speaker":"Đoạn văn","vi":"Thứ Bảy Vương Nhất Tuyết ở nhà nấu cơm, xem tivi, chơi với các con và chú chó nhỏ, Dương Đồng Nhạc cũng có một chú chó nhỏ."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"那是陈天中的第二本中文书，他明天上午在学校学习。\" (Đó là quyển sách tiếng Trung thứ hai của Trần Thiên Trung, sáng ngày mai anh ấy học ở trường.), nên đáp án đúng là 陈天中.","options":["李文","白家月","陈天中","杨同乐"],"q":"谁明天上午在学校学习？"},{"answerIdx":3,"explanation":"Trong bài có câu \"王一雪星期六在家里做饭、看电视，和孩子们、小狗玩\" (Thứ Bảy Vương Nhất Tuyết ở nhà nấu cơm, xem tivi, chơi với các con và chó con), nên đáp án đúng là 做饭、看电视，和孩子们、小狗玩.","options":["读书、唱歌、看电影","学习、买书、听歌","看电视、去外边唱歌","做饭、看电视，和孩子们、小狗玩"],"q":"王一雪星期六在家里做什么？"}],"scene":"总结本课三篇课文的内容。","sceneVi":"Tóm tắt nội dung ba bài khóa trong bài 9."}],"hsk1-10":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"请问，有杯子吗？","pinyin":"Qǐngwèn, yǒu bēizi ma?","speaker":"王一雪","vi":"Xin hỏi, ở đây có cốc không ạ?"},{"hanzi":"有，杯子在这边。","pinyin":"Yǒu, bēizi zài zhèbiān.","speaker":"售货员","vi":"Có ạ, cốc ở bên này."},{"hanzi":"多少钱一个？","pinyin":"Duōshao qián yí gè?","speaker":"王一雪","vi":"Bao nhiêu tiền một cái ạ?"},{"hanzi":"这些五块钱一个，那些十块钱一个。","pinyin":"Zhèxiē wǔ kuài qián yí gè, nàxiē shí kuài qián yí gè.","speaker":"售货员","vi":"Những cái này năm tệ một cái, những cái kia mười tệ một cái."},{"hanzi":"我买这个吧。","pinyin":"Wǒ mǎi zhège ba.","speaker":"王一雪","vi":"Tôi mua cái này nhé."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, người bán hàng nói \"这些五块钱一个，那些十块钱一个。\" (Những cái này năm tệ một cái, những cái kia mười tệ một cái.), nên đáp án đúng là 这些五块，那些十块.","options":["都是五块钱一个","都是十块钱一个","这些五块，那些十块","这些十块，那些五块"],"q":"小店里的杯子多少钱一个？"},{"answerIdx":1,"explanation":"Trong bài, người bán giới thiệu \"这些五块钱一个，那些十块钱一个。\" (Những cái này 5 tệ một cái, những cái kia 10 tệ một cái.) và Vương Nhất Tuyết nói \"我买这个吧。\" (Tôi mua cái này nhé - tức loại gần chỗ cô ấy giá 5 tệ), nên đáp án đúng là 买五块钱的这个.","options":["买十块钱的那个","买五块钱的这个","她不买杯子","她买两个杯子"],"q":"王一雪买哪个杯子？"}],"scene":"在一家小店，王一雪在买杯子。","sceneVi":"Trong một cửa hàng nhỏ, Vương Nhất Tuyết đang mua cốc."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"这儿的水果真不少！","pinyin":"Zhèr de shuǐguǒ zhēn bù shǎo!","speaker":"王一雪","vi":"Hoa quả ở đây thật nhiều!"},{"hanzi":"您想买什么？","pinyin":"Nín xiǎng mǎi shénme?","speaker":"售货员","vi":"Chị muốn mua gì ạ?"},{"hanzi":"我想买两斤苹果。","pinyin":"Wǒ xiǎng mǎi liǎng jīn píngguǒ.","speaker":"王一雪","vi":"Tôi muốn mua hai cân táo."},{"hanzi":"苹果三块五一斤。这些七块二，七块钱吧。","pinyin":"Píngguǒ sān kuài wǔ yì jīn. Zhèxiē qī kuài èr, qī kuài qián ba.","speaker":"售货员","vi":"Táo ba tệ rưỡi một cân. Chỗ này bảy tệ hai hào, tính chẵn bảy tệ nhé."},{"hanzi":"好的，这儿的苹果真便宜！","pinyin":"Hǎo de, zhèr de píngguǒ zhēn piányi!","speaker":"王一雪","vi":"Vâng, táo ở đây rẻ thật đấy!"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Vương Nhất Tuyết nói \"我想买两斤苹果。\" (Tôi muốn mua hai cân táo.) và người bán nói \"苹果三块五一斤。\" (Táo giá ba tệ rưỡi một cân.), nên đáp án đúng là 三块五一斤，想买两斤.","options":["三块五一斤，想买两斤","三块钱一斤，想买两斤","七块二一斤，想买一斤","三块五一斤，想买三斤"],"q":"苹果多少钱一斤？王一雪想买多少？"},{"answerIdx":1,"explanation":"Trong bài, người bán hàng nói \"这些七块二，七块钱吧。\" (Chỗ này bảy tệ hai hào, tính tròn bảy tệ nhé.), nên đáp án đúng là 七块钱.","options":["七块二","七块钱","三块五","六块钱"],"q":"这些苹果七块二，售货员说多少钱？"}],"scene":"在菜市场，王一雪在买水果。","sceneVi":"Ở chợ rau quả, Vương Nhất Tuyết đang mua hoa quả."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"这家商店衣服真多！这件一百元，怎么样？","pinyin":"Zhè jiā shāngdiàn yīfu zhēn duō! Zhè jiàn yìbǎi yuán, zěnmeyàng?","speaker":"王一雪","vi":"Cửa hàng này nhiều quần áo thật! Chiếc này một trăm tệ, anh thấy thế nào?"},{"hanzi":"好看，也不贵。","pinyin":"Hǎokàn, yě bú guì.","speaker":"刘明","vi":"Đẹp đấy, cũng không đắt."},{"hanzi":"小雪能穿，买一件吧。","pinyin":"Xiǎoxuě néng chuān, mǎi yí jiàn ba.","speaker":"王一雪","vi":"Tiểu Tuyết mặc vừa đấy, mua một chiếc nhé."},{"hanzi":"好的。小明能穿吗？","pinyin":"Hǎo de. Xiǎomíng néng chuān ma?","speaker":"刘明","vi":"Được. Tiểu Minh có mặc được không?"},{"hanzi":"不能。这些是女孩子穿的衣服，男孩子的衣服在那儿。","pinyin":"Bù néng. Zhèxiē shì nǚ háizi chuān de yīfu, nán háizi de yīfu zài nàr.","speaker":"王一雪","vi":"Không được. Đây là quần áo cho bé gái mặc, quần áo của bé trai ở đằng kia."},{"hanzi":"好的。","pinyin":"Hǎo de.","speaker":"刘明","vi":"Được rồi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết hỏi về chiếc áo 100 tệ \"这件一百元，怎么样？\" (Cái này 100 tệ, thấy sao?), Lưu Minh trả lời \"好看，也不贵。\" (Đẹp, cũng không đắt.), nên đáp án đúng là 好看，也不贵.","options":["不好看，很贵","好看，但是很贵","好看，也不贵","不好看，也不贵"],"q":"刘明觉得那件一百元的衣服怎么样？"},{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết giải thích \"不能。这些是女孩子穿的衣服，男孩子的衣服在那儿。\" (Không được. Đây là quần áo con gái mặc, quần áo của con trai ở đằng kia.), nên đáp án đúng là 因为这些是女孩子穿的衣服.","options":["因为这些衣服太贵了","因为这些是女孩子穿的衣服","因为商店没有男孩子的衣服","因为小明不喜欢这件衣服"],"q":"为什么小明不能穿这些衣服？"}],"scene":"在商场里，刘明和王一雪在给孩子买衣服。","sceneVi":"Trong trung tâm thương mại, Lưu Minh và Vương Nhất Tuyết đang mua quần áo cho con."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"在一家小店，王一雪买杯子，这些五块钱一个，那些十块钱一个，她买这个。","pinyin":"Zài yì jiā xiǎo diàn, Wáng Yīxuě mǎi bēizi, zhèxiē wǔ kuài qián yí gè, nàxiē shí kuài qián yí gè, tā mǎi zhège.","speaker":"Đoạn văn","vi":"Ở một cửa hàng nhỏ, Vương Nhất Tuyết mua cốc, những cái này năm tệ một cái, những cái kia mười tệ một cái, cô ấy mua cái này."},{"hanzi":"在菜市场，王一雪买两斤苹果，苹果三块五一斤，售货员说七块钱吧，这儿的苹果真便宜！","pinyin":"Zài càishìchǎng, Wáng Yīxuě mǎi liǎng jīn píngguǒ, píngguǒ sān kuài wǔ yì jīn, shòuhuòyuán shuō qī kuài qián ba, zhèr de píngguǒ zhēn piányi!","speaker":"Đoạn văn","vi":"Ở chợ rau quả, Vương Nhất Tuyết mua hai cân táo, táo ba tệ rưỡi một cân, người bán nói tính bảy tệ nhé, táo ở đây rẻ thật!"},{"hanzi":"在商场里，刘明和王一雪给孩子买衣服，这家商店衣服真多，有一件一百元，好看也不贵。","pinyin":"Zài shāngchǎng li, Liú Míng hé Wáng Yīxuě gěi háizi mǎi yīfu, zhè jiā shāngdiàn yīfu zhēn duō, yǒu yí jiàn yìbǎi yuán, hǎokàn yě bú guì.","speaker":"Đoạn văn","vi":"Trong trung tâm thương mại, Lưu Minh và Vương Nhất Tuyết mua quần áo cho con, cửa hàng này thật nhiều quần áo, có một chiếc giá một trăm tệ, đẹp mà cũng không đắt."},{"hanzi":"小雪能穿这件女孩子穿的衣服，男孩子的衣服在那儿。","pinyin":"Xiǎoxuě néng chuān zhè jiàn nǚ háizi chuān de yīfu, nán háizi de yīfu zài nàr.","speaker":"Đoạn văn","vi":"Tiểu Tuyết mặc được chiếc áo dành cho bé gái này, còn quần áo của bé trai ở đằng kia."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"在菜市场，王一雪买两斤苹果... 售货员说七块钱吧\" (Ở chợ rau, Vương Nhất Tuyết mua hai cân táo... người bán nói bảy tệ nhé), nên đáp án đúng là 在菜市场，给了七块钱.","options":["在商场，给了一百元","在小店，给了五块钱","在菜市场，给了七块钱","在菜市场，给了三块五"],"q":"王一雪在哪儿买苹果？给了多少钱？"},{"answerIdx":1,"explanation":"Trong bài có câu \"有一件一百元，好看也不贵。小雪能穿这件女孩子穿的衣服\" (Có một chiếc áo giá 100 tệ, đẹp mà không đắt. Tiểu Tuyết có thể mặc chiếc áo dành cho bé gái này), nên đáp án đúng là 小雪.","options":["小明","小雪","刘明","售货员"],"q":"商场里那件一百元的衣服，谁能穿？"}],"scene":"总结本课三篇课文的内容。","sceneVi":"Tóm tắt nội dung ba bài khóa trong bài 10."}],"hsk1-11":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"喂，李文，你什么时候能到饭店？","pinyin":"Wèi, Lǐ Wén, nǐ shénme shíhou néng dào fàndiàn?","speaker":"王一飞","vi":"A-lô, Lý Văn, khi nào bạn có thể đến nhà hàng?"},{"hanzi":"还不知道，正在找呢。它是不是在超市后边？","pinyin":"Hái bù zhīdào, zhèngzài zhǎo ne. Tā shì bu shì zài chāoshì hòubian?","speaker":"李文","vi":"Vẫn chưa biết, tôi đang tìm đây. Có phải nó ở phía sau siêu thị không?"},{"hanzi":"是的。你开车没开车？","pinyin":"Shì de. Nǐ kāichē méi kāichē?","speaker":"王一飞","vi":"Đúng vậy. Bạn có lái xe không?"},{"hanzi":"我没开车，坐车呢。","pinyin":"Wǒ méi kāichē, zuò chē ne.","speaker":"李文","vi":"Tôi không lái xe, tôi đang ngồi xe (đi xe)."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lý Văn hỏi \"它是不是在超市后边？\" (Có phải nó ở phía sau siêu thị không?) và Vương Nhất Phi xác nhận \"是的。\" (Đúng vậy.), nên đáp án đúng là 在超市后边.","options":["在超市前边","在超市后边","在学校外边","在电影院里边"],"q":"李文找的饭店在哪儿？"},{"answerIdx":2,"explanation":"Trong bài, Lý Văn nói \"我没开车，坐车呢。\" (Tôi không lái xe, đang ngồi xe đây.), nên đáp án đúng là 他坐车去.","options":["他开车去","他走路去","他坐车去","他骑车去"],"q":"李文怎么去饭店？"}],"scene":"在路上，李文在找饭店，王一飞给他打电话。","sceneVi":"Trên đường đi, Lý Văn đang tìm nhà hàng, Vương Nhất Phi gọi điện cho anh ấy."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你还在读大学吗？","pinyin":"Nǐ hái zài dú dàxué ma?","speaker":"王一飞","vi":"Bạn vẫn đang học đại học à?"},{"hanzi":"对，我读大学呢，还是大学生。","pinyin":"Duì, wǒ dú dàxué ne, hái shì dàxuéshēng.","speaker":"李文","vi":"Đúng vậy, tôi đang học đại học, vẫn là sinh viên đại học."},{"hanzi":"你们学习忙不忙？","pinyin":"Nǐmen xuéxí máng bu máng?","speaker":"王一飞","vi":"Việc học của các bạn có bận không?"},{"hanzi":"非常忙，我学医，我们的课很多。","pinyin":"Fēicháng máng, wǒ xué yī, wǒmen de kè hěn duō.","speaker":"李文","vi":"Vô cùng bận, tôi học ngành y, tiết học của chúng tôi rất nhiều."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Lý Văn nói \"对，我读大学呢，还是大学生。\" (Đúng, tôi đang học đại học, vẫn là sinh viên đại học.), nên đáp án đúng là 他在读大学.","options":["他在饭店工作","他在医院工作","他在读大学","他在家休息"],"q":"李文现在在做什么？"},{"answerIdx":1,"explanation":"Trong bài, khi được hỏi \"你们学习忙不忙？\" (Việc học của các bạn có bận không?), Lý Văn trả lời \"非常忙，我学医，我们的课很多。\" (Rất bận, tôi học y, tiết học của chúng tôi rất nhiều.), nên đáp án đúng là 学医，非常忙.","options":["学中文，不忙","学医，非常忙","学医，不太忙","学中文，非常忙"],"q":"李文学什么？他们的学习忙吗？"}],"scene":"在饭店里，王一飞和李文见面后聊天儿。","sceneVi":"Ở trong nhà hàng, sau khi gặp mặt, Vương Nhất Phi và Lý Văn nói chuyện phiếm."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"弟弟起床没起床呢？","pinyin":"Dìdi qǐchuáng méi qǐchuáng ne?","speaker":"刘明","vi":"Em trai đã thức dậy chưa?"},{"hanzi":"没起床呢，还在睡觉。","pinyin":"Méi qǐchuáng ne, hái zài shuìjiào.","speaker":"刘小雪","vi":"Chưa dậy đâu ạ, vẫn đang ngủ."},{"hanzi":"还睡呢？他今天去不去那里？","pinyin":"Hái shuì ne? Tā jīntiān qù bu qù nàlǐ?","speaker":"刘明","vi":"Vẫn ngủ à? Hôm nay em ấy có đến chỗ đó không?"},{"hanzi":"去哪里？","pinyin":"Qù nǎlǐ?","speaker":"刘小雪","vi":"Đến đâu ạ?"},{"hanzi":"去超市。","pinyin":"Qù chāoshì.","speaker":"刘明","vi":"Đến siêu thị."},{"hanzi":"我昨天问他，他对我说，他不去，他今天要和小朋友玩。","pinyin":"Wǒ zuótiān wèn tā, tā duì wǒ shuō, tā bú qù, tā jīntiān yào hé xiǎopéngyǒu wán.","speaker":"刘小雪","vi":"Hôm qua con hỏi em ấy rồi, em ấy nói với con là em ấy không đi, hôm nay em ấy muốn chơi cùng các bạn nhỏ."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi Lưu Minh hỏi em trai đã dậy chưa, Lưu Tiểu Tuyết trả lời \"没起床呢，还在睡觉。\" (Chưa dậy đâu ạ, vẫn đang ngủ.), nên đáp án đúng là 还在睡觉.","options":["正在吃饭","还在睡觉","已经去超市了","在和小朋友玩"],"q":"刘明问女儿的时候，弟弟在做什么？"},{"answerIdx":3,"explanation":"Trong bài, Lưu Tiểu Tuyết nói \"他不去，他今天要和小朋友玩。\" (Em ấy không đi, hôm nay em ấy muốn chơi với các bạn nhỏ.), nên đáp án đúng là 和小朋友玩.","options":["和爸爸去医院","和姐姐去超市","在家里睡觉一天","和小朋友玩"],"q":"弟弟今天要做什么？"}],"scene":"星期六早上，刘明要去医院加班，出门前和女儿对话。","sceneVi":"Sáng thứ Bảy, Lưu Minh chuẩn bị đến bệnh viện làm thêm giờ, trước khi ra khỏi nhà ông nói chuyện với con gái."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"李文没开车，坐车去超市后边的饭店。","pinyin":"Lǐ Wén méi kāichē, zuò chē qù chāoshì hòubian de fàndiàn.","speaker":"Đoạn văn","vi":"Lý Văn không lái xe, anh ấy ngồi xe đến nhà hàng ở phía sau siêu thị."},{"hanzi":"在饭店里，李文对王一飞说，他在读大学，他学医，课很多。","pinyin":"Zài fàndiàn lǐ, Lǐ Wén duì Wáng Yīfēi shuō, tā zài dú dàxué, tā xué yī, kè hěn duō.","speaker":"Đoạn văn","vi":"Trong nhà hàng, Lý Văn nói với Vương Nhất Phi rằng anh ấy đang học đại học, anh ấy học ngành y và có rất nhiều tiết học."},{"hanzi":"星期六早上，刘明问刘小雪弟弟起床没起床。","pinyin":"Xīngqīliù zǎoshang, Liú Míng wèn Liú Xiǎoxuě dìdi qǐchuáng méi qǐchuáng.","speaker":"Đoạn văn","vi":"Sáng thứ Bảy, Lưu Minh hỏi Lưu Tiểu Tuyết xem em trai đã thức dậy chưa."},{"hanzi":"弟弟还在睡觉，他今天不去超市，要和小朋友玩。","pinyin":"Dìdi hái zài shuìjiào, tā jīntiān bú qù chāoshì, yào hé xiǎopéngyǒu wán.","speaker":"Đoạn văn","vi":"Em trai vẫn đang ngủ, hôm nay em ấy không đi siêu thị mà muốn chơi cùng các bạn nhỏ."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"在饭店里，李文对王一飞说，他在读大学，他学医，课很多。\" (Ở nhà hàng, Lý Văn nói với Vương Nhất Phi rằng anh đang học đại học, học ngành y, rất nhiều tiết học.), nên đáp án đúng là 王一飞.","options":["刘明","刘小雪","王一飞","小朋友"],"q":"李文在超市后边的饭店里和谁说话？"},{"answerIdx":1,"explanation":"Trong bài có câu \"李文对王一飞说，他在读大学，他学医\" (Lý Văn nói với Vương Nhất Phi rằng anh đang học đại học, học y), còn các lựa chọn khác đều sai so với nội dung bài (Lý Văn ngồi xe chứ không tự lái, em trai vẫn đang ngủ và hôm nay không đi siêu thị), nên đáp án đúng là 李文在读大学，学医.","options":["李文开车去饭店","李文在读大学，学医","弟弟已经起床了","弟弟今天要去超市"],"q":"下面哪句话是对的？"}],"scene":"课文一至三的故事总结。","sceneVi":"Tóm tắt câu chuyện của Bài khóa 1 đến 3."}],"hsk1-12":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"今天天气怎么样？","pinyin":"Jīntiān tiānqì zěnmeyàng?","speaker":"王一雪","vi":"Hôm nay thời tiết thế nào?"},{"hanzi":"这里的天不太好，下雨了。","pinyin":"Zhèlǐ de tiān bú tài hǎo, xià yǔ le.","speaker":"王一飞","vi":"Trời ở đây không tốt lắm, mưa rồi."},{"hanzi":"雨大吗？","pinyin":"Yǔ dà ma?","speaker":"王一雪","vi":"Mưa có to không?"},{"hanzi":"有点儿大，我觉得很冷。","pinyin":"Yǒudiǎnr dà, wǒ juéde hěn lěng.","speaker":"王一飞","vi":"Hơi to, tôi cảm thấy rất lạnh."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Phi nói \"这里的天不太好，下雨了。\" (Thời tiết ở đây không tốt lắm, trời mưa rồi.), nên đáp án đúng là 不太好，下雨了.","options":["天气很好","下雪了","不太好，下雨了","很热，没下雨"],"q":"王一飞那儿今天天气怎么样？"},{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Phi trả lời về cơn mưa \"有点儿大，我觉得很冷。\" (Hơi to một chút, tôi thấy rất lạnh.), nên đáp án đúng là 雨有点儿大，她觉得很冷.","options":["雨不大，她觉得很热","雨有点儿大，她觉得很冷","雨很大，她不觉得冷","没下雨，她觉得有点儿冷"],"q":"王一飞那儿的雨大吗？她觉得怎么样？"}],"scene":"王一雪给王一飞打电话，询问王一飞那边的情况。","sceneVi":"Vương Nhất Tuyết gọi điện cho Vương Nhất Phi, hỏi thăm tình hình bên chỗ Vương Nhất Phi."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"昨天下雪了。","pinyin":"Zuótiān xià xuě le.","speaker":"王一雪","vi":"Hôm qua tuyết rơi rồi."},{"hanzi":"是的，太冷了。","pinyin":"Shì de, tài lěng le.","speaker":"杨同乐","vi":"Đúng vậy, lạnh quá đi."},{"hanzi":"你昨天没来公司，生病了？","pinyin":"Nǐ zuótiān méi lái gōngsī, shēngbìng le?","speaker":"王一雪","vi":"Hôm qua bạn không đến công ty, bị ốm à?"},{"hanzi":"对，我昨天去医院看病了。","pinyin":"Duì, wǒ zuótiān qù yīyuàn kànbìng le.","speaker":"杨同乐","vi":"Đúng vậy, hôm qua tôi đã đến bệnh viện khám bệnh."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói \"昨天下雪了。\" (Hôm qua trời đổ tuyết rồi.) và Dương Đồng Nhạc đáp \"是的，太冷了。\" (Đúng vậy, lạnh quá.), nên đáp án đúng là 下雪了，太冷了.","options":["下雨了，不冷","下雪了，太冷了","天气很好，很热","没下雪，有点儿冷"],"q":"他们那儿昨天的天气怎么样？"},{"answerIdx":2,"explanation":"Trong bài, khi được hỏi có phải bị ốm không, Dương Đồng Nhạc đáp \"对，我昨天去医院看病了。\" (Đúng, hôm qua tôi đã đi bệnh viện khám bệnh.), nên đáp án đúng là 他生病了，去医院看病了.","options":["他去外边唱歌了","他在家看电视了","他生病了，去医院看病了","他去学校学习了"],"q":"杨同乐昨天为什么没来公司？"}],"scene":"在公司电梯里，王一雪和杨同乐在聊天儿。","sceneVi":"Trong thang máy công ty, Vương Nhất Tuyết và Dương Đồng Nhạc đang nói chuyện phiếm."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"医生，我病了。","pinyin":"Yīshēng, wǒ bìng le.","speaker":"杨同乐","vi":"Bác sĩ ơi, tôi bị ốm rồi."},{"hanzi":"我看看。你觉得怎么样？","pinyin":"Wǒ kànkan. Nǐ juéde zěnmeyàng?","speaker":"胡医生","vi":"Để tôi xem chút. Anh cảm thấy thế nào?"},{"hanzi":"我很冷。","pinyin":"Wǒ hěn lěng.","speaker":"杨同乐","vi":"Tôi rất lạnh."},{"hanzi":"好的，吃一点儿药，今天休息半天吧。","pinyin":"Hǎo de, chī yìdiǎnr yào, jīntiān xiūxi bàn tiān ba.","speaker":"胡医生","vi":"Được rồi, uống một chút thuốc, hôm nay nghỉ ngơi nửa ngày đi nhé."},{"hanzi":"好的。","pinyin":"Hǎo de.","speaker":"杨同乐","vi":"Vâng ạ."},{"hanzi":"回家后再喝些热水。","pinyin":"Huí jiā hòu zài hē xiē rè shuǐ.","speaker":"胡医生","vi":"Sau khi về nhà hãy uống thêm chút nước ấm nhé."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, khi bác sĩ Hồ hỏi \"你觉得怎么样？\" (Anh cảm thấy thế nào?), Dương Đồng Nhạc trả lời \"我很冷。\" (Tôi rất lạnh.), nên đáp án đúng là 很冷.","options":["很冷","很热","很忙","很好"],"q":"杨同乐看病时，对胡医生说自己觉得怎么样？"},{"answerIdx":2,"explanation":"Trong bài, bác sĩ Hồ dặn \"吃一点儿药，今天休息半天吧。\" (Uống một chút thuốc, hôm nay nghỉ nửa ngày nhé.) và \"回家后再喝些热水。\" (Sau khi về nhà uống thêm chút nước nóng nữa.), nên đáp án đúng là 吃一点儿药，休息半天，回家后再喝些热水.","options":["去公司上班，多喝冷水","吃药，休息一天，去外边玩","吃一点儿药，休息半天，回家后再喝些热水","不吃药，在医院休息半天"],"q":"胡医生让杨同乐做什么？"}],"scene":"昨天在医院，医生给杨同乐看病。","sceneVi":"Hôm qua ở bệnh viện, bác sĩ khám bệnh cho Dương Đồng Nhạc."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"王一飞那里的天不太好，下雨了，她觉得很冷。","pinyin":"Wáng Yīfēi nàlǐ de tiān bú tài hǎo, xià yǔ le, tā juéde hěn lěng.","speaker":"Đoạn văn","vi":"Trời bên chỗ Vương Nhất Phi không tốt lắm, trời mưa rồi, cô ấy cảm thấy rất lạnh."},{"hanzi":"王一雪这里昨天下雪了，天气太冷了。","pinyin":"Wáng Yīxuě zhèlǐ zuótiān xià xuě le, tiānqì tài lěng le.","speaker":"Đoạn văn","vi":"Bên chỗ Vương Nhất Tuyết hôm qua tuyết rơi rồi, thời tiết lạnh quá."},{"hanzi":"杨同乐昨天生病了，没来公司，他去医院看病了。","pinyin":"Yáng Tónglè zuótiān shēngbìng le, méi lái gōngsī, tā qù yīyuàn kànbìng le.","speaker":"Đoạn văn","vi":"Dương Đồng Nhạc hôm qua bị ốm, không đến công ty, anh ấy đã đi bệnh viện khám bệnh."},{"hanzi":"胡医生对杨同乐说，吃一点儿药，休息半天，回家后再喝些热水。","pinyin":"Hú yīshēng duì Yáng Tónglè shuō, chī yìdiǎnr yào, xiūxi bàn tiān, huí jiā hòu zài hē xiē rè shuǐ.","speaker":"Đoạn văn","vi":"Bác sĩ Hồ nói với Dương Đồng Nhạc uống một chút thuốc, nghỉ ngơi nửa ngày, sau khi về nhà hãy uống thêm chút nước ấm."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"王一飞那里的天不太好，下雨了\" (Thời tiết chỗ Vương Nhất Phi không tốt lắm, trời mưa) và \"王一雪这里昨天下雪了\" (Chỗ Vương Nhất Tuyết hôm qua có tuyết rơi), nên đáp án đúng là 王一飞那里下雨了，王一雪这里昨天下雪了.","options":["王一飞那里下雪了，王一雪这里下雨了","王一飞那里下雨了，王一雪这里昨天下雪了","两个地方都下雨了，都不冷","王一飞那里很热，王一雪这里很冷"],"q":"王一飞那里和王一雪这里的天气有什么不一样？"},{"answerIdx":2,"explanation":"Trong bài có câu \"胡医生对杨同乐说，吃一点儿药，休息半天，回家后再喝些热水。\" (Bác sĩ Hồ nói với Dương Đồng Nhạc: uống chút thuốc, nghỉ nửa ngày, sau khi về nhà uống thêm chút nước nóng.), nên đáp án đúng là 喝些热水.","options":["看电视","做饭","喝些热水","睡觉"],"q":"除了吃药和休息半天，胡医生还让杨同乐回家后做什么？"}],"scene":"课文一至三的故事总结。","sceneVi":"Tóm tắt câu chuyện của Bài khóa 1 đến 3."}],"hsk1-13":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"王老师，我可以再问您一个问题吗？","pinyin":"Wáng lǎoshī, wǒ kěyǐ zài wèn nín yí gè wèntí ma?","speaker":"白家月","vi":"Thưa cô Vương, em có thể hỏi cô thêm một câu hỏi nữa không ạ?"},{"hanzi":"可以。你有什么问题？","pinyin":"Kěyǐ. Nǐ yǒu shénme wèntí?","speaker":"王一飞","vi":"Được chứ. Em có câu hỏi gì?"},{"hanzi":"那个小店卖不卖手机？","pinyin":"Nàge xiǎo diàn mài bu mài shǒujī?","speaker":"白家月","vi":"Cửa hàng nhỏ kia có bán điện thoại di động không ạ?"},{"hanzi":"我不知道。你可以打电话问一下。","pinyin":"Wǒ bù zhīdào. Nǐ kěyǐ dǎ diànhuà wèn yíxià.","speaker":"王一飞","vi":"Cô không biết. Em có thể gọi điện thoại hỏi thử xem."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"那个小店卖不卖手机？\" (\"Cửa hàng nhỏ kia có bán điện thoại không?\"), nên Bạch Gia Nguyệt đang hỏi cô Vương về việc cửa hàng nhỏ đó có bán điện thoại hay không.","options":["那个小店卖不卖手机","王老师的手机号码是多少","那个小店在哪里","王老师买不买手机"],"q":"白家月问王老师什么问题？"},{"answerIdx":2,"explanation":"Trong bài, cô Vương trả lời \"我不知道。你可以打电话问一下。\" (\"Tôi không biết. Em có thể gọi điện hỏi thử xem.\"), nên đáp án đúng là cô nói mình không biết và bảo Bạch Gia Nguyệt gọi điện hỏi thử.","options":["她说那个小店不卖手机。","她说她知道那个小店在哪里。","她说她不知道，让白家月打电话问一下。","她说她可以去小店帮白家月买手机。"],"q":"王老师怎么回答白家月的问题？"}],"scene":"在教室里，下课后，白家月问王老师问题。","sceneVi":"Trong phòng học, sau giờ tan học, Bạch Gia Nguyệt hỏi cô Vương một câu hỏi."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"女士，请坐！您喝什么？","pinyin":"Nǚshì, qǐng zuò! Nín hē shénme?","speaker":"服务员","vi":"Thưa quý cô, mời ngồi! Cô uống gì ạ?"},{"hanzi":"我看一下。请给我一杯牛奶。","pinyin":"Wǒ kàn yíxià. Qǐng gěi wǒ yì bēi niúnǎi.","speaker":"王一雪","vi":"Để tôi xem một chút. Làm ơn cho tôi một cốc sữa bò."},{"hanzi":"好的。您还要什么？","pinyin":"Hǎo de. Nín hái yào shénme?","speaker":"服务员","vi":"Vâng ạ. Cô còn muốn gọi thêm gì nữa không?"},{"hanzi":"我还没吃早饭，再要这个面包和鸡蛋吧。","pinyin":"Wǒ hái méi chī zǎofàn, zài yào zhège miànbāo hé jīdàn ba.","speaker":"王一雪","vi":"Tôi vẫn chưa ăn sáng, lấy thêm cái bánh mì và trứng gà này nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"请给我一杯牛奶。\" (\"Làm ơn cho tôi một cốc sữa bò.\"), nên đồ uống Vương Nhất Tuyết muốn gọi là một cốc sữa bò.","options":["一杯茶","一杯牛奶","一杯咖啡","一杯水"],"q":"王一雪想喝什么？"},{"answerIdx":0,"explanation":"Trong bài có câu \"我还没吃早饭，再要这个面包和鸡蛋吧。\" (\"Tôi vẫn chưa ăn sáng, lấy thêm cái bánh mì này và trứng gà nữa nhé.\"), nên lý do là vì cô ấy chưa ăn sáng.","options":["因为她还没吃早饭。","因为她想给朋友买。","因为她最喜欢喝牛奶。","因为她晚上没吃饭。"],"q":"王一雪为什么还要面包和鸡蛋？"}],"scene":"在咖啡馆里，王一雪想吃早餐。","sceneVi":"Ở trong quán cà phê, Vương Nhất Tuyết muốn ăn bữa sáng."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"先生，请坐！您要什么？","pinyin":"Xiānsheng, qǐng zuò! Nín yào shénme?","speaker":"服务员","vi":"Thưa ông, mời ngồi! Ông muốn gọi gì ạ?"},{"hanzi":"我要一斤饺子。","pinyin":"Wǒ yào yì jīn jiǎozi.","speaker":"刘明","vi":"Tôi muốn một cân (nửa ký) sủi cảo."},{"hanzi":"好的。一斤饺子40个。","pinyin":"Hǎo de. Yì jīn jiǎozi sìshí gè.","speaker":"服务员","vi":"Vâng ạ. Một cân sủi cảo có 40 cái."},{"hanzi":"40个太多了，我要一半吧。","pinyin":"Sìshí gè tài duō le, wǒ yào yíbàn ba.","speaker":"刘明","vi":"40 cái nhiều quá rồi, tôi lấy một nửa thôi nhé."},{"hanzi":"半斤20个。您想喝什么？","pinyin":"Bàn jīn èrshí gè. Nín xiǎng hē shénme?","speaker":"服务员","vi":"Nửa cân là 20 cái. Ông muốn uống gì ạ?"},{"hanzi":"请给我一杯茶吧。","pinyin":"Qǐng gěi wǒ yì bēi chá ba.","speaker":"刘明","vi":"Làm ơn cho tôi một tách trà nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"40个太多了，我要一半吧。\" (\"40 cái nhiều quá, tôi lấy một nửa thôi.\") và người phục vụ xác nhận \"半斤20个。\" (\"Nửa cân là 20 cái.\"), nên cuối cùng Lưu Minh gọi 20 cái sủi cảo.","options":["十个","二十个","三十个","四十个"],"q":"刘明最后要了多少个饺子？"},{"answerIdx":0,"explanation":"Khi được hỏi \"您想喝什么？\" (\"Anh muốn uống gì?\"), Lưu Minh trả lời \"请给我一杯茶吧。\" (\"Làm ơn cho tôi một cốc trà nhé.\"), nên ngoài sủi cảo anh ấy gọi thêm một cốc trà.","options":["一杯茶","一杯牛奶","一杯咖啡","一点儿水"],"q":"除了饺子，刘明还想喝什么？"}],"scene":"在餐馆里，刘明在点餐。","sceneVi":"Ở trong nhà hàng, Lưu Minh đang gọi món."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"下课后，白家月问王老师那个小店卖不卖手机，王老师不知道，她说白家月可以打电话问一下。","pinyin":"Xiàkè hòu, Bái Jiāyuè wèn Wáng lǎoshī nàge xiǎo diàn mài bu mài shǒujī, Wáng lǎoshī bù zhīdào, tā shuō Bái Jiāyuè kěyǐ dǎ diànhuà wèn yíxià.","speaker":"Đoạn văn","vi":"Sau giờ tan học, Bạch Gia Nguyệt hỏi cô Vương xem cửa hàng nhỏ kia có bán điện thoại không, cô Vương không biết và bảo Bạch Gia Nguyệt có thể gọi điện hỏi thử."},{"hanzi":"在咖啡馆里，王一雪还没吃早饭，她要一杯牛奶，再要这个面包和鸡蛋。","pinyin":"Zài kāfēiguǎn lǐ, Wáng Yīxuě hái méi chī zǎofàn, tā yào yì bēi niúnǎi, zài yào zhège miànbāo hé jīdàn.","speaker":"Đoạn văn","vi":"Ở quán cà phê, Vương Nhất Tuyết vẫn chưa ăn sáng, cô gọi một cốc sữa bò, rồi gọi thêm bánh mì và trứng gà."},{"hanzi":"在餐馆里，一斤饺子40个太多了，刘明要一半，再要一杯茶。","pinyin":"Zài cānguǎn lǐ, yì jīn jiǎozi sìshí gè tài duō le, Liú Míng yào yíbàn, zài yào yì bēi chá.","speaker":"Đoạn văn","vi":"Ở nhà hàng, một cân sủi cảo 40 cái nhiều quá, Lưu Minh gọi một nửa, rồi gọi thêm một tách trà."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"在咖啡馆里，王一雪还没吃早饭，她要一杯牛奶，再要这个面包和鸡蛋。\" (\"Ở quán cà phê, Vương Nhất Tuyết vẫn chưa ăn sáng, cô gọi một cốc sữa bò, lấy thêm bánh mì này và trứng gà.\"), nên đáp án đúng là một cốc sữa bò, bánh mì và trứng gà.","options":["一杯茶和饺子","一杯牛奶和饺子","一杯牛奶、面包和鸡蛋","一杯咖啡、面包和鸡蛋"],"q":"在咖啡馆里，王一雪要了什么？"},{"answerIdx":2,"explanation":"Trong bài có câu \"在餐馆里，一斤饺子40个太多了，刘明要一半，再要一杯茶。\" (\"Ở nhà hàng, một cân sủi cảo 40 cái nhiều quá, Lưu Minh lấy một nửa, gọi thêm một cốc trà.\"), nên lý do anh ấy chỉ gọi một nửa là vì 40 cái quá nhiều.","options":["因为他不爱吃饺子。","因为他想喝茶，不想吃东西。","因为四十个太多了。","因为餐馆里只有二十个饺子。"],"q":"刘明为什么只要一半饺子？"}],"scene":"总结第13课的三篇课文。","sceneVi":"Tóm tắt ba bài khóa của Bài 13."}],"hsk1-14":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"你们上火车后看见王老师了吗？","pinyin":"Nǐmen shàng huǒchē hòu kànjiàn Wáng lǎoshī le ma?","speaker":"白家月","vi":"Sau khi lên tàu hỏa, các bạn có nhìn thấy cô Vương không?"},{"hanzi":"没看见。中午车开后，有些人在看书，有些人睡觉了。","pinyin":"Méi kànjiàn. Zhōngwǔ chē kāi hòu, yǒuxiē rén zài kàn shū, yǒuxiē rén shuìjiào le.","speaker":"陈天中","vi":"Không thấy. Buổi trưa sau khi tàu chạy, một số người đang đọc sách, một số người đi ngủ rồi."},{"hanzi":"你呢？","pinyin":"Nǐ ne?","speaker":"白家月","vi":"Còn bạn thì sao?"},{"hanzi":"我看了一个电影。","pinyin":"Wǒ kànle yí gè diànyǐng.","speaker":"陈天中","vi":"Tôi đã xem một bộ phim."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, khi Bạch Gia Nguyệt hỏi \"你们上火车后看见王老师了吗？\" (\"Sau khi lên tàu hỏa các cậu có nhìn thấy cô Vương không?\"), Trần Thiên Trung đáp \"没看见。\" (\"Không thấy.\"), nên đáp án đúng là không nhìn thấy.","options":["看见了，王老师在看书。","看见了，王老师在睡觉。","没看见。","看见了，王老师在看电影。"],"q":"上火车后，陈天中看见王老师了吗？"},{"answerIdx":1,"explanation":"Trong bài có câu \"我看了一个电影。\" (\"Mình đã xem một bộ phim.\"), nên sau khi tàu chạy vào buổi trưa, Trần Thiên Trung đã xem một bộ phim.","options":["他在看书。","他看了一个电影。","他睡觉了。","他和王老师说话。"],"q":"中午车开后，陈天中在火车上做什么？"}],"scene":"在教室里，下课后，白家月和陈天中在谈论上一次课外旅行。","sceneVi":"Trong phòng học, sau giờ tan học, Bạch Gia Nguyệt và Trần Thiên Trung đang nói chuyện về chuyến đi ngoại khóa lần trước."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你们会说汉语了，也会写汉字了吗？","pinyin":"Nǐmen huì shuō Hànyǔ le, yě huì xiě Hànzì le ma?","speaker":"王一飞","vi":"Các em đã biết nói tiếng Hán rồi, cũng biết viết chữ Hán rồi chứ?"},{"hanzi":"我们都会写了。","pinyin":"Wǒmen dōu huì xiě le.","speaker":"白家月","vi":"Chúng em đều biết viết rồi ạ."},{"hanzi":"老师，我听不见。","pinyin":"Lǎoshī, wǒ tīng bú jiàn.","speaker":"陈天中","vi":"Thưa cô, em không nghe rõ ạ."},{"hanzi":"请大家不要说话！请听老师的问题：你们都会写哪些汉字了？","pinyin":"Qǐng dàjiā búyào shuōhuà! Qǐng tīng lǎoshī de wèntí: Nǐmen dōu huì xiě nǎxiē Hànzì le?","speaker":"王一飞","vi":"Mọi người đừng nói chuyện nữa! Hãy nghe câu hỏi của cô: Các em đều đã biết viết những chữ Hán nào rồi?"},{"hanzi":"我会写这些字了，您看！","pinyin":"Wǒ huì xiě zhèxiē zì le, nín kàn!","speaker":"陈天中","vi":"Em biết viết những chữ này rồi, cô xem ạ!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"老师，我听不见。\" (\"Thưa cô, em không nghe thấy ạ.\") và ngay sau đó cô Vương nói \"请大家不要说话！请听老师的问题\" (\"Mời cả lớp đừng nói chuyện! Hãy nghe câu hỏi của cô\"), nên cô nhắc cả lớp giữ trật tự là vì Trần Thiên Trung không nghe rõ.","options":["因为要下课了。","因为陈天中听不见老师的问题。","因为白家月想睡觉。","因为大家不会说汉语。"],"q":"王老师为什么请大家不要说话？"},{"answerIdx":0,"explanation":"Ở cuối bài khóa, Trần Thiên Trung nói \"我会写这些字了，您看！\" (\"Em biết viết những chữ này rồi, cô xem ạ!\"), chứng tỏ bạn ấy đã biết viết một số chữ Hán.","options":["会写一些字了。","还不会写。","他听不见，所以没写。","他只会说汉语，不会写字。"],"q":"最后，陈天中会写汉字了吗？"}],"scene":"在课堂上，王一飞询问学生们的学习情况。","sceneVi":"Trong giờ học trên lớp, Vương Nhất Phi hỏi thăm tình hình học tập của các học sinh."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"明年女儿上中学。","pinyin":"Míngnián nǚ'ér shàng zhōngxué.","speaker":"刘明","vi":"Sang năm con gái lên cấp hai (trung học)."},{"hanzi":"对。儿子也上小学了。","pinyin":"Duì. Érzi yě shàng xiǎoxué le.","speaker":"王一雪","vi":"Đúng vậy. Con trai cũng vào tiểu học rồi."},{"hanzi":"我们家有了一个中学生。","pinyin":"Wǒmen jiā yǒule yí gè zhōngxuéshēng.","speaker":"刘明","vi":"Nhà mình có một học sinh trung học rồi."},{"hanzi":"还有了一个小学生。","pinyin":"Hái yǒule yí gè xiǎoxuéshēng.","speaker":"王一雪","vi":"Còn có thêm một học sinh tiểu học nữa."},{"hanzi":"上学后，他们都忙了。","pinyin":"Shàngxué hòu, tāmen dōu máng le.","speaker":"刘明","vi":"Sau khi đi học, chúng đều bận rộn cả rồi."},{"hanzi":"是的。太晚了，睡觉吧。","pinyin":"Shì de. Tài wǎn le, shuìjiào ba.","speaker":"王一雪","vi":"Phải đấy. Muộn quá rồi, đi ngủ thôi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có hai câu \"明年女儿上中学。\" (\"Sang năm con gái lên cấp hai.\") và \"儿子也上小学了。\" (\"Con trai cũng vào tiểu học rồi.\"), nên con gái học trung học và con trai học tiểu học.","options":["女儿上小学，儿子上中学。","女儿上中学，儿子上小学。","女儿和儿子都上中学。","女儿和儿子都上小学。"],"q":"明年他们的女儿和儿子上什么学校？"},{"answerIdx":0,"explanation":"Trong bài có câu \"上学后，他们都忙了。\" (\"Sau khi đi học, bọn trẻ đều bận rộn cả rồi.\"), nên Lưu Minh nhận xét rằng sau khi đi học các con đều trở nên bận rộn.","options":["他们都很忙。","他们都爱睡觉。","他们不说话了。","他们去坐火车。"],"q":"刘明说孩子们上学后怎么样？"}],"scene":"在家里，刘明和王一雪在谈论孩子的升学情况。","sceneVi":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang bàn về việc lên lớp chuyển cấp của các con."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"上火车后，陈天中没看见王老师，中午车开后，他看了一个电影。","pinyin":"Shàng huǒchē hòu, Chén Tiānzhōng méi kànjiàn Wáng lǎoshī, zhōngwǔ chē kāi hòu, tā kànle yí gè diànyǐng.","speaker":"Đoạn văn","vi":"Sau khi lên tàu hỏa, Trần Thiên Trung không nhìn thấy cô Vương, buổi trưa sau khi tàu chạy, cậu ấy đã xem một bộ phim."},{"hanzi":"在课堂上，同学们都会说汉语、写汉字了，陈天中也写了一些字给王老师看。","pinyin":"Zài kètáng shàng, tóngxuémen dōu huì shuō Hànyǔ, xiě Hànzì le, Chén Tiānzhōng yě xiěle yìxiē zì gěi Wáng lǎoshī kàn.","speaker":"Đoạn văn","vi":"Trên lớp học, các bạn học đều đã biết nói tiếng Hán, viết chữ Hán, Trần Thiên Trung cũng viết một số chữ cho cô Vương xem."},{"hanzi":"明年刘明和王一雪的女儿上中学、儿子上小学了，上学后孩子们都忙了。","pinyin":"Míngnián Liú Míng hé Wáng Yīxuě de nǚ'ér shàng zhōngxué, érzi shàng xiǎoxué le, shàngxué hòu háizimen dōu máng le.","speaker":"Đoạn văn","vi":"Sang năm con gái của Lưu Minh và Vương Nhất Tuyết lên trung học, con trai vào tiểu học, sau khi đi học bọn trẻ đều bận rộn cả."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"上火车后，陈天中没看见王老师，中午车开后，他看了一个电影。\" (\"Sau khi lên tàu hỏa, Trần Thiên Trung không nhìn thấy cô Vương; sau khi tàu chạy vào buổi trưa, cậu ấy đã xem một bộ phim.\"), nên thời điểm xem phim là sau khi tàu chạy vào buổi trưa.","options":["上午上课的时候","中午火车开后","晚上睡觉前","下课后在教室里"],"q":"陈天中是什么时候看电影的？"},{"answerIdx":0,"explanation":"Trong bài có câu \"在课堂上，同学们都会说汉语、写汉字了，陈天中也写了一些字给王老师看。\" (\"Trên lớp, các bạn học đều đã biết nói tiếng Hán và viết chữ Hán, Trần Thiên Trung cũng viết một số chữ cho cô Vương xem.\"), nên đáp án đúng là cả lớp đều biết nói tiếng Hán và viết chữ Hán.","options":["都会说汉语，也会写汉字了。","只会说汉语，还不会写汉字。","只有白家月会写汉字。","陈天中没有写汉字。"],"q":"同学们在课堂上的汉语学习情况怎么样？"}],"scene":"总结第14课的三篇课文。","sceneVi":"Tóm tắt ba bài khóa của Bài 14."}],"hsk1-15":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"你们爱吃哪个菜？","pinyin":"Nǐmen ài chī nǎge cài?","speaker":"李文","vi":"Các bạn thích ăn món nào?"},{"hanzi":"我喜欢这个，也喜欢那个。","pinyin":"Wǒ xǐhuan zhège, yě xǐhuan nàge.","speaker":"白家月","vi":"Tôi thích món này, cũng thích món kia."},{"hanzi":"这些菜都好吃，还很好看。","pinyin":"Zhèxiē cài dōu hǎochī, hái hěn hǎokàn.","speaker":"陈天中","vi":"Những món này đều ngon, lại còn rất đẹp mắt."},{"hanzi":"我爱吃中国菜，也喜欢做。大家多吃点儿。","pinyin":"Wǒ ài chī Zhōngguó cài, yě xǐhuan zuò. Dàjiā duō chī diǎnr.","speaker":"李文","vi":"Tôi thích ăn món Trung Quốc, cũng thích nấu nữa. Mọi người ăn nhiều một chút nhé."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"这些菜都好吃，还很好看。\" (\"Những món này đều ngon, lại còn rất đẹp mắt nữa.\"), nên Trần Thiên Trung khen các món ăn vừa ngon vừa đẹp mắt.","options":["太辣了，不好吃。","只有一点儿好看。","都好吃，还很好看。","不太好看，但是很好吃。"],"q":"陈天中觉得这些菜怎么样？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我爱吃中国菜，也喜欢做。\" (\"Mình thích ăn món Trung Quốc, cũng thích nấu nữa.\"), nên thông tin đúng về Lý Văn là anh ấy vừa thích ăn vừa thích nấu món Trung Quốc.","options":["他不爱吃中国菜。","他只会吃，不会做中国菜。","他爱吃中国菜，也喜欢做。","他请朋友去餐馆吃饭。"],"q":"关于李文，下面哪句话是对的？"}],"scene":"在李文家，李文邀请陈天中、白家月等朋友品尝中餐。","sceneVi":"Tại nhà Lý Văn, Lý Văn mời các bạn như Trần Thiên Trung, Bạch Gia Nguyệt thưởng thức món ăn Trung Quốc."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你们都想去哪儿？","pinyin":"Nǐmen dōu xiǎng qù nǎr?","speaker":"李文","vi":"Các bạn đều muốn đi đâu?"},{"hanzi":"去年我和男朋友去了西安，今年我想去北京。","pinyin":"Qùnián wǒ hé nánpéngyou qùle Xī'ān, jīnnián wǒ xiǎng qù Běijīng.","speaker":"安妮","vi":"Năm ngoái tôi và bạn trai đã đi Tây An, năm nay tôi muốn đi Bắc Kinh."},{"hanzi":"前几年我去了西安，非常好玩儿。今年我也想去北京。","pinyin":"Qián jǐ nián wǒ qùle Xī'ān, fēicháng hǎowánr. Jīnnián wǒ yě xiǎng qù Běijīng.","speaker":"白家月","vi":"Mấy năm trước tôi đã đi Tây An, rất thú vị. Năm nay tôi cũng muốn đi Bắc Kinh."},{"hanzi":"我和王老师都是北京人，北京非常漂亮。","pinyin":"Wǒ hé Wáng lǎoshī dōu shì Běijīng rén, Běijīng fēicháng piàoliang.","speaker":"李文","vi":"Tôi và cô Vương đều là người Bắc Kinh, Bắc Kinh vô cùng xinh đẹp."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, An Ni nói \"去年我和男朋友去了西安，今年我想去北京。\" (\"Năm ngoái mình và bạn trai đã đi Tây An, năm nay mình muốn đi Bắc Kinh.\"), nên năm ngoái An Ni đã cùng bạn trai đi Tây An.","options":["她和男朋友去了北京。","她和男朋友去了西安。","她和白家月去了西安。","她和王老师去了北京。"],"q":"去年安妮做什么了？"},{"answerIdx":0,"explanation":"Trong bài, Lý Văn nói \"我和王老师都是北京人，北京非常漂亮。\" (\"Mình và cô Vương đều là người Bắc Kinh, Bắc Kinh rất đẹp.\"), nên người Bắc Kinh là Lý Văn và cô Vương.","options":["李文和王老师","安妮和白家月","李文和安妮","白家月和王老师"],"q":"谁是北京人？"}],"scene":"在李文家，大家边吃饭边谈论假期计划。","sceneVi":"Tại nhà Lý Văn, mọi người vừa ăn cơm vừa bàn luận về kế hoạch kỳ nghỉ."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"你们的飞机到北京要几个小时？","pinyin":"Nǐmen de fēijī dào Běijīng yào jǐ gè xiǎoshí?","speaker":"王一飞","vi":"Chuyến bay của các em đến Bắc Kinh mất mấy tiếng?"},{"hanzi":"九个小时。","pinyin":"Jiǔ gè xiǎoshí.","speaker":"白家月","vi":"Chín tiếng ạ."},{"hanzi":"我家人都在北京，星期天我姐姐也有时间，她可以去机场接你们，你们也可以住我家。","pinyin":"Wǒ jiārén dōu zài Běijīng, Xīngqītiān wǒ jiějie yě yǒu shíjiān, tā kěyǐ qù jīchǎng jiē nǐmen, nǐmen yě kěyǐ zhù wǒ jiā.","speaker":"王一飞","vi":"Người nhà cô đều ở Bắc Kinh, Chủ nhật chị gái cô cũng có thời gian, chị ấy có thể ra sân bay đón các em, các em cũng có thể ở nhà cô."},{"hanzi":"我们星期日早上八点到大兴机场，早不早？","pinyin":"Wǒmen Xīngqīrì zǎoshang bā diǎn dào Dàxīng Jīchǎng, zǎo bu zǎo?","speaker":"安妮","vi":"Sáng Chủ nhật 8 giờ bọn em đến sân bay Đại Hưng, có sớm quá không ạ?"},{"hanzi":"不早。","pinyin":"Bù zǎo.","speaker":"王一飞","vi":"Không sớm đâu."},{"hanzi":"谢谢老师！那我们和您姐姐在大兴机场见！","pinyin":"Xièxie lǎoshī! Nà wǒmen hé nín jiějie zài Dàxīng Jīchǎng jiàn!","speaker":"白家月","vi":"Em cảm ơn cô ạ! Vậy bọn em hẹn gặp chị gái cô ở sân bay Đại Hưng nhé!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"星期天我姐姐也有时间，她可以去机场接你们\" (\"Chủ nhật chị gái cô cũng rảnh, chị ấy có thể ra sân bay đón các em\"), nên người ra sân bay đón là chị gái của cô Vương.","options":["王老师","王老师的姐姐","李文","安妮的男朋友"],"q":"星期天谁可以去机场接白家月和安妮？"},{"answerIdx":1,"explanation":"Trong bài có câu \"九个小时。\" (\"Chín tiếng.\") và \"我们星期日早上八点到大兴机场\" (\"Chúng em đến sân bay Đại Hưng vào lúc 8 giờ sáng Chủ nhật\"), nên chuyến bay mất 9 tiếng và đến nơi lúc 8 giờ sáng Chủ nhật.","options":["要八个小时，星期天早上九点到。","要九个小时，星期天早上八点到。","要九个小时，星期六早上八点到。","要八个小时，星期天晚上八点到。"],"q":"她们坐飞机去北京要几个小时，什么时候到？"}],"scene":"在教室外，白家月、安妮和王老师在谈论去北京旅游的事。","sceneVi":"Ngoài phòng học, Bạch Gia Nguyệt, An Ni và cô Vương đang nói chuyện về việc đi du lịch Bắc Kinh."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"李文爱吃中国菜，也喜欢做，陈天中和白家月觉得这些菜都好吃，还很好看。","pinyin":"Lǐ Wén ài chī Zhōngguó cài, yě xǐhuan zuò, Chén Tiānzhōng hé Bái Jiāyuè juéde zhèxiē cài dōu hǎochī, hái hěn hǎokàn.","speaker":"Đoạn văn","vi":"Lý Văn thích ăn món Trung Quốc và cũng thích nấu, Trần Thiên Trung và Bạch Gia Nguyệt thấy những món này đều ngon, lại còn rất đẹp mắt."},{"hanzi":"去年安妮和男朋友去了西安，前几年白家月也去了西安，今年她们都想去北京。","pinyin":"Qùnián Ānnī hé nánpéngyou qùle Xī'ān, qián jǐ nián Bái Jiāyuè yě qùle Xī'ān, jīnnián tāmen dōu xiǎng qù Běijīng.","speaker":"Đoạn văn","vi":"Năm ngoái An Ni và bạn trai đã đi Tây An, mấy năm trước Bạch Gia Nguyệt cũng đã đi Tây An, năm nay hai bạn đều muốn đi Bắc Kinh."},{"hanzi":"李文和王老师都是北京人，王老师的家人都在北京。","pinyin":"Lǐ Wén hé Wáng lǎoshī dōu shì Běijīng rén, Wáng lǎoshī de jiārén dōu zài Běijīng.","speaker":"Đoạn văn","vi":"Lý Văn và cô Vương đều là người Bắc Kinh, người nhà của cô Vương đều ở Bắc Kinh."},{"hanzi":"安妮和白家月坐飞机去北京要九个小时，星期天早上八点到大兴机场，王老师的姐姐可以去机场接她们，她们也可以住王老师家。","pinyin":"Ānnī hé Bái Jiāyuè zuò fēijī qù Běijīng yào jiǔ gè xiǎoshí, Xīngqītiān zǎoshang bā diǎn dào Dàxīng Jīchǎng, Wáng lǎoshī de jiějie kěyǐ qù jīchǎng jiē tāmen, tāmen yě kěyǐ zhù Wáng lǎoshī jiā.","speaker":"Đoạn văn","vi":"An Ni và Bạch Gia Nguyệt đi máy bay đến Bắc Kinh mất chín tiếng, 8 giờ sáng Chủ nhật đến sân bay Đại Hưng, chị gái của cô Vương có thể ra sân bay đón họ, họ cũng có thể ở nhà cô Vương."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"去年安妮和男朋友去了西安，前几年白家月也去了西安，今年她们都想去北京。\" (\"Năm ngoái An Ni và bạn trai đã đi Tây An, mấy năm trước Bạch Gia Nguyệt cũng từng đi Tây An, năm nay hai cô ấy đều muốn đi Bắc Kinh.\"), nên điểm chung là cả hai đều từng đi Tây An và năm nay đều muốn đi Bắc Kinh.","options":["她们去年一起去了西安。","她们今年都想去西安。","她们都去过西安，今年都想去北京。","她们都是北京人。"],"q":"关于安妮和白家月，下面哪句话是对的？"},{"answerIdx":1,"explanation":"Trong bài có câu \"王老师的姐姐可以去机场接她们，她们也可以住王老师家。\" (\"Chị gái của cô Vương có thể ra sân bay đón họ, và họ cũng có thể ở nhà cô Vương.\"), nên gia đình cô Vương giúp đón ở sân bay và cho ở nhờ tại nhà.","options":["给她们做中国菜和买机票。","王老师的姐姐可以去机场接她们，她们也可以住王老师家。","王老师自己去机场接她们，还带她们去西安。","带她们去咖啡馆吃早饭。"],"q":"她们到北京后，王老师的家人可以帮她们做什么？"}],"scene":"总结李文、陈天中、白家月、安妮和王老师的故事。","sceneVi":"Tóm tắt câu chuyện của Lý Văn, Trần Thiên Trung, Bạch Gia Nguyệt, An Ni và cô Vương."}]});
